insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "9843908f-773e-4b02-9939-542dc41c12e9", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 0, "content": "Ariel Macrae (00:02): The outverse is intended as a place to connect your favorite artists, athletes, et cetera, even closer with the community, while adding benefit and utility to the users and helping provide additional support for nonprofits that we care about. So some of the intention with it was just as a way to kind of build a better financial situation for creators. That's really how we got involved with it and how the Rome team kind of came in.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing podcast. My name is Cole Hallborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Heur, and today I'm sitting down with Ariel McCrae. She's the social media and marketing manager over at Outside Inc. Ariel, how are you?\n\nAriel Macrae (01:16): I'm good, thanks. Hi, Cole.\n\nCole Heilborn (01:18): Yeah, thanks for joining us today. Where are you calling in from?\n\nAriel Macrae (01:22): I live in beautiful North Lake Tahoe in California.\n\nCole Heilborn (01:26): Okay, right on. And your week's going? Well,\n\nAriel Macrae (01:29): It is. We're having a pretty good summer here. It's been hot, but thankfully so far no major fire scares, which is kind of a common thing for us, unfortunately. And so we've been able to get out and just enjoy some gorgeous summer weather instead of smoke.\n\nCole Heilborn (01:45): That's great to hear. I feel like this summer has been fairly mild in terms of fire season, at least compared to last year. I feel like at this point last year there was way more burning, at least here in Washington and especially down near you guys, right?", "token_estimate": 524, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:45", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "7a55b37b-58e4-4510-8b56-2b0477eaca4b", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 1, "content": "Ariel Macrae (02:02): Yeah, definitely. It was a bit of a scary one for us, a couple years in a row actually with numerous fires going around northern California. So really happy to say that we haven't had as much of that this summer so far, and hopefully, knock on wood, it keeps up.\n\nCole Heilborn (02:16): Yeah. Well, I'm very much looking forward to our episode today. We've got a fun one. We're going to be discussing the outer verse and word of caution. I guess this is a topic that I don't know a whole lot about. I know what I've read on some of the articles that you guys have published, and obviously we've connected and you've kind of filled me in on some of the background, but Web3 and the Metaverse and all this new technology and fts are stuff that I know a little bit about, I don't know a lot about. And so we've had some great conversations on the podcast about this technology and how it's changing our industry, and you guys are a great example of how you've embraced this technology. So I'm super excited to dive into this with you.\n\nAriel Macrae (03:06): Yeah, it's a really interesting space, I think personally coming in on this project that it's got so much potential and we're really only just starting to dip our toe into it. So I'm excited to talk to you about it some more.\n\nCole Heilborn (03:20): So if you could first start by maybe giving us a little bit of background. How long have you been with outside? What's your role and how does your role connect to the Outverse?", "token_estimate": 376, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "02:02", "end_timestamp": "03:20", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "4a5c6bf6-e50f-4896-bd1c-20ac68d3cc15", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 2, "content": "Ariel Macrae (03:32): Yeah, so I've been with outside now, we're looking at about nine months technically. My company, Rome Media was actually acquired last year, so full-time. I've been with Rome almost two years, but we were one of the companies that outside acquired last year and came into this project with an expertise in community management, content influencer and athlete relationships and things like that. And so coming into outside, we've kind of been trying to figure out what our niche here is. And one of the things that was really a big directive from Robin Thurston, who's the CEO of the company, was trying to get into this Web3 venture and see how we can embrace this new technology in the world of outdoors and how it can be something beneficial for everybody here. And I think one of the big things why the Rome team in particular was attracted to this is the relationship with the creators that are involved. So that's kind of how we got started on it. I manage all the social media and marketing, all the brand messaging that goes out on our public facing channels, and I'm definitely also really new to this whole crypto and NFT and Web3 space. So it's been an interesting learning experience for me for sure.\n\nCole Heilborn (04:54): And for folks who aren't familiar, what's the background on Rome media? What do you guys do or how does that work?", "token_estimate": 343, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "03:32", "end_timestamp": "04:54", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "add6142d-57dc-412a-959b-302e2af267f2", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 3, "content": "Ariel Macrae (05:01): Yeah, so Rome Media was founded in conjunction with a number of athletes, photographers of that nature. So some of the founding members include Jimmy Chin and Conrad Anchor, Chris Burkart, Sasha de Gilian, Rebecca Rush. We've got this long list of just really amazing athletes and artists and photographers and just people heavily involved in influential in the outdoor industry. And they kind of came into this all as a team, as a way to connect more with the community. And Rome has really been this evolving space, helping to get out curated content from all of these creators as well as just other up and coming people in the outdoor space and trying to connect our audience, which is a pretty large one for other creators and athletes to get and get their work out there in the world and become known. We've done a lot of work with branded campaigns and things of that nature, but I think the things we're proudest of are our unique content and our ability to help spread out that content and movies and films and series and things like that, really original stuff on the web. (06:26): So it's been a really fun thing to kind of see that evolution. So I would say Rome really started with this group of founding members as a place for them to connect with their audience and with the community and create this exclusive space for people who are interested in these people to learn more about projects and content and things like they had going on. And over the years, it's really evolved. It started as a hosting place for their content, and then it's kind of become more of a way for the outdoor community become connected with up and coming creators. We had the Rome Awards a number of years ago before the pandemic. Things changed a little bit, but we kind of called that the Oscars, the outdoor industry. So it was a cool place for photographers and filmers and things like that to showcase their work. (07:18): And then we started our R Academy, which was focused on learning, thinking, masterclass style, outdoor education, coming from the best of the best in these fields. So you could learn about climbing and photography from Jimmy Chin, or you could learn about biking from Rebecca Rush, or you could learn about all these different things from these amazing talented people and also create an exclusive connection with them. So when we were acquired by outside, it was those aspects. It was both the community relationship and the learning and education piece that we've brought into outside and are becoming a new part of what's going on here at this company now.", "token_estimate": 651, "speakers": ["Ariel Macrae"], "start_timestamp": "05:01", "end_timestamp": "05:01", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "863cec56-8b6e-43d3-8631-6a66ea1800e3", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 4, "content": "Cole Heilborn (08:01): Very cool. And when were you acquired?\n\nAriel Macrae (08:04): Oh gosh. I'm so bad with the timeline, but it was sometime around last November. So yeah, it's been a little bit of time since then and we're still kind of finding how all of these different pieces and all these different companies that were acquired by outside in the past couple of years are fitting together, and that'll all be part of what the new offerings of outside as a whole are moving forward.\n\nCole Heilborn (08:28): Yeah, gotcha. So was it back in April that the outer verse was announced?\n\nAriel Macrae (08:35): Yep. Yeah, we announced it, I think it was mid April. So it's been kind of a whirlwind in terms of launching a project and only a couple months to get this whole thing off the ground. And so it's been a really exciting, fast-paced adventure for us.\n\nCole Heilborn (08:53): And let's start simple. How would you define the Outverse?\n\nAriel Macrae (08:58): So the Outverse is intended as a place to connect your favorite artists, athletes, et cetera, even closer with the community, while adding benefit and utility to the users and helping provide additional support for nonprofits that we care about. So some of the intention with it was just as a way to really kind of build a better financial situation for creators. That's really how we got involved with it and how the Rome team came in because the traditional social media model and online model has not been really super financially supportive of the creators. The brands are the ones taking the finance and the profits and everything is really benefiting them and not so much the people who are actually making the content. So that was how we started coming into it, and it's something that's continuing to evolve and we're figuring out how it's going to move forward. But as I mentioned before, there's so much opportunity and so much utility that can come out of it.\n\nCole Heilborn (10:08): So could you give some background and break down what you're describing here, this challenge of creators and compensation and how that all connects to the outer verse?", "token_estimate": 532, "speakers": ["Cole Heilborn", "Ariel Macrae"], "start_timestamp": "08:01", "end_timestamp": "10:08", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "860ea081-746a-4ab8-9f1c-e41cfd03822f", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 5, "content": "Ariel Macrae (10:20): Yeah, so the intention is to really make this a place that the creators can find some financial freedom. So when they create a piece of art and they push it out to the audience, the majority of the profits are going to be going directly to them. So we're kind of acting as a marketplace in the sense that we're taking a processing fee, but a large portion of the proceeds of any sale of their NFTs moving forward, be going directly to them as well as a portion going to our nonprofit partners. We currently work with Protect Our Winters Access Fund people for bikes and big city mountaineers. So a portion of every NFT sale is also going to those nonprofits too.\n\nCole Heilborn (11:05): Okay, very cool. But the challenge though that you guys have seen is that brands will typically be the ones who are profiting off of these types of art pieces. And what sort of an environment is that the case and how is this model trying to get more money into the creator's pocket?\n\nAriel Macrae (11:24): Yeah, so I mean, if you think about what the traditional model on Instagram is, if a brand were to partner with an influencer ambassador, athlete, et cetera, or whatever your nomenclature is for them, they are traditionally given a one-time fee and it's negotiable based on their number of followers and things of that nature. But ultimately, profits seen from that are generally going mostly to the brand involved. The creator gets a very small portion. So this has kind of flipped that on its head where instead of the majority going to the brand and less going to the creator, it's really the other way around. So that's a big part of why we were excited to become involved with it, especially coming from this place of being a community based social brand.\n\nCole Heilborn (12:14): Okay, gotcha. And what is the goal? What's the big picture goal for the outer verse?", "token_estimate": 471, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "10:20", "end_timestamp": "12:14", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "1fe3b76d-a3b3-4de0-8d8d-f1d789d87b66", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 6, "content": "Ariel Macrae (12:21): I think what we are really trying to figure out is how to utilize new technology in a way that's beneficial and helps encourage more people to get outside. So outside as a company, our really big thing, our goal, our vision is just getting more people outside. And we've done so much research about how people are just spending so much time on their screens and not enough time outside actually enjoying that time outside. And it seems counterintuitive that would be using online and internet platforms to try and get people to actually spend less time online, but we're trying to figure out how to tap into this new technology and use that as a way to encourage people to get outside. I think the thing, people are always really resistant to change, especially when it comes to technology. I'll use the example for myself personally of when smartphones first came out, which really dates me, but back in the day when they first came out for many years, it was just like, why do I even need that? (13:24): What is the purpose of it? I don't need to go on the internet constantly. I don't need to be having a camera attached to my phone, et cetera. But over the years, we've seen how that has just become such a central part of our lives, and I think the vision here with Web3 and trying to just embrace this technology early and just be early adapters and figure out how we can use this in a positive way is really what the aim of the outer verse is. It's really, I think, going to continue to just change and evolve. And so the challenge we're facing right now is everyone wants to know the exact specifics of what we're doing with it, and we're still figuring it out in a lot of ways, but we know that there's all this opportunity, for instance, attaching move to earn utility to our apps and things like that. So if you look at Gaia and t TR Forks, there's ways that eventually we're hoping to tie in NFTs and blockchain technology to be able to say, oh, we can see that you got outside, you went for a trail run, you went for a bike ride, et cetera. You've earned points from that and then come back here and we're going to reward you for it. So we're trying to figure out how to best use this technology to make it something that gives people positive reward for that outside time.", "token_estimate": 577, "speakers": ["Ariel Macrae"], "start_timestamp": "12:21", "end_timestamp": "12:21", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "2591b730-bb78-4cbe-86af-641648d161df", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 7, "content": "Cole Heilborn (14:50): Yeah. So you, something interesting that you guys have been doing a bunch of research on electronic usage and how the increase in that. Do you have any of that handy? I'm curious what you found.\n\nAriel Macrae (15:04): For us, it was just the average person spends seven to nine hours their day on a screen and only seven minutes outside. Six or seven minutes I believe was the number we came out. So it's like you're thinking about the normal person, maybe not so much within our niche of people who are super passionate about the outdoors, but just looking at the average cell phone computer user out there and saying, these people really are not spending very much time outside. It might be walking from their house to their car, from their car to an office, or even less of that nowadays with people working remote and things like that. So it really has become such a problem where people are so sunk into their screen life that they're not spending as much time outside. And we've jokingly but not jokingly referred to ourselves as the anti metaverse because if you think about what Facebook and Meta are doing, it's like they're trying to get people to embrace this AR technology and this whole metaverse, which great, you're going outside on a virtual reality headpiece rather than actually doing it in real life, and that is the opposite of what we want to see.\n\nCole Heilborn (16:17): Yeah, I feel like I've seen that description pop up a number of times as I was doing some research on the outverse. Yes, the anti metaverse or the opposite of the Metaverse. I got a few chuckles out of that. What is the platform built on? You guys are working off of, I don't know how to pronounce it, the cel?\n\nAriel Macrae (16:37): Solana? Yeah,\n\nCole Heilborn (16:38): Solana. Okay.", "token_estimate": 451, "speakers": ["Cole Heilborn", "Ariel Macrae"], "start_timestamp": "14:50", "end_timestamp": "16:38", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "e16656a9-e8c9-4672-9a32-44a5762b14f7", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 8, "content": "Ariel Macrae (16:39): Yeah. So it's complicated for people who are not crypto educated, and I count myself in that it's a really complex thing out. There are so many different types of blockchain and blockchain really is just that. That is the chain of information that is storing the data about each person who has purchased that unique NFT or unique piece of crypto or whatever. It's just simple language being the thing that is storing your data and carrying it across the platforms to verify that this piece belongs to you. And so for us, we chose Solana in particular because out of all of the major mass known and used blockchains out there, it is the one that is recognized to have one of the lowest energy impacts. So that was crucial for us because you'll see a lot of the negative feedback or connotations about NFTs and blockchains and things of that nature are that it's really bad for the environment. (17:47): And traditional blockchain is blockchain like crypto and Ethereum. They use so much energy because every time they have to verify a purchase or verify someone's chain, it's running it through so many systems and using just tons and tons of energy to process. Whereas Solana is super low energy. So the comparison we like to make from the info that they've shared with us is that one Solana transaction is basically the equivalent of doing two Google searches on your computer, which all of us do so many on a daily basis. The reality of these things that we do frequently that are energy users like that, a lot of people don't even consider it, but NFTs blockchain, they just have this kind of bad reputation of being bad for the environment. And so we're kind of trying to not necessarily prove people wrong, but just give them the information that this is not that and it is energy efficient and it is, we're moving in the direction of just trying to continually be conscious and sustainable.", "token_estimate": 480, "speakers": ["Ariel Macrae"], "start_timestamp": "16:39", "end_timestamp": "16:39", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "2556085f-b1fc-4144-8be5-7b01484b5ec2", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 9, "content": "Cole Heilborn (18:56): Yeah, no, that's great. I don't know that I've ever considered how much energy does a Google search use, but now it's got me thinking about a whole bunch of other questions. So the outverse launched in April. What does the current state of it look like today?\n\nAriel Macrae (19:12): Yeah, so officially our first launching project was what was called the Outverse Passport. And what that is is kind of like this VIP access and it's the initial people who are buying in and saying, Hey, I want to be a part of this and I want to have early access and I want to have special benefits and things of that nature. And we actually, that officially launched on July 20th to the public and we had 10,000 up for Mint, and I don't know what our final numbers are right now. There's still some for Saleable and Open Sea, which is an alternative purchase platform for NFTs, but everyone who bought into that early Mint is getting, first of all an outside plus membership included. So they're getting access to all of the things that we have available in terms of content, subscriptions, apps, all of that. They're getting ongoing benefits where they're going to get early access, meaning they can purchase or other upcoming NFTs before anyone else can. (20:20): So the benefit being there that if we have someone that's super desirable and potentially will sell out really fast, these people are going to get first dibs on it. They're also going to get a ton of other benefits. As I keep mentioning, it's continuing to learn and develop exactly what we can do with this technology, so we know there's going to be things tied to that in the future. Like I talked about potentially that utility token, which is that move to earn tie in with the apps and passport holders are going to get things like multipliers, they'll earn more than the average user just for going out and doing those things, and that'll potentially give them access to stuff like events and screenings and content and exclusives. So there's just so much there. It's a lot to unpack, and it's also just in, its really infancy right now, but that was our very first drop. (21:14): We're super excited about it. Then we have some other really exciting drops coming up very shortly. Our next one is going to be with an artist named James Arnold, and that's focused all on cycling. So it's tied in with everything we're doing with our biking for all campaign and outside, which is just trying to get people outside and on bikes. And the art is just super cool and fun, really unique, and we're psyched to have him as our first artist creator on the platform. Then after that, we'll have all of our roadmap creators. We've got Chris ard, Sasha de Gilian, Malik Malik The Martian is what he calls himself and Biju Thomas. Those will be the first people that come out with their artwork or their NFT drops and benefits and things like that. And then we'll continue to move forward into next year working with a lot more exciting creators and coming out with new features and benefits.", "token_estimate": 764, "speakers": ["Cole Heilborn", "Ariel Macrae"], "start_timestamp": "18:56", "end_timestamp": "19:12", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "de10fdcc-c5fc-4fc1-8b5d-6dedaec67f1d", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 10, "content": "Cole Heilborn (22:11): Gotcha. So I guess this is one of the areas where I start to, I don't know, I get confused or I start to have lots of questions. So when an NFT Mint comes out first, could you explain what a mint means? What is that definition?\n\nAriel Macrae (22:28): So basically what an NFT is, it's what you call generative art. So we use AI software to put in all of these unique pieces of artwork that the software then generates. So that let's say for the instance of the passport, we generated 10,000 unique images. So each one that's tied to a particular blockchain address is different. So we have 10,000 different pieces of art. And so that's what a mint is. It's when you mint, you get your unique piece of art, and that's what is tied to your wallet address, which is basically a digital version of a wallet you're holding it. It contains the address of your blockchain and the information about your purchase. Yeah,\n\nCole Heilborn (23:18): Okay. So for example, with the second launch that you have coming up, so you'll sell a unique piece of art, and then with that, there's other benefits that come along with the particular NFT as well.", "token_estimate": 290, "speakers": ["Cole Heilborn", "Ariel Macrae"], "start_timestamp": "22:11", "end_timestamp": "23:18", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "b33e0a34-5bf4-48f6-a3c9-1ebb1fe055b1", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 11, "content": "Ariel Macrae (23:34): Yeah, so each NFTs have different things attached to it, and I can't release too much info on what the specifics of those each are right now, but really unique, interesting thing about doing something like this is everyone who makes a purchase, we can then potentially look at their wallet address and drop things to them. So it's a ticket to an event, it's some kind of discount, it's giveaway, it's things of that nature. One great example, when we first launched the project, we offered a free NFT called our Bedrock badge just as a way to get people kind of familiar with the platform. And this was before we actually launched the purchase passport. So everyone had access to our bedrock NFT if they wanted to sign up, and they went and created a wallet, they dropped the bedrock in there, and then just for being a bedrock holder, they were automatically entered to a giveaway and we give away a ton of cool water bottles, headlamps, camp cookware, things of that nature, and they just had to claim this badge. And then we picked winners based on that and shipped them out real life benefit prizes. They also got entered into a giveaway we were doing with Jack Johnson where we gave away a bunch of signed vinyls and we gave away concert tickets and VIP experiences and things of that nature. So it's cool just like they signed up for this one thing, and then we can tie in all these other benefits that we can drop to them later on as we add more and do more with it.\n\nCole Heilborn (25:05): So obviously one of the benefits of an NFT is that it's unique and it's yours and that inherently, and if there's a limited run of an NFT, then that inherently creates value. And in some instances we've heard stories where NFTs have an extremely high appreciation rate in terms of value. Other times they plummet in value and people lose money on them. Walk me through your guys' thought process in terms of the market and the value of these NFTs and what that could look like in the future.", "token_estimate": 503, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "23:34", "end_timestamp": "25:05", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "f94dd351-8e05-4f71-b357-0101238ecd63", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 12, "content": "Ariel Macrae (25:39): Yeah, so I mean, it's interesting. Obviously I think the news is talking a lot about how we're kind of in this crypto winter right now, and the market's definitely taken a downturn. I think it's any sort of investing, there's ups and downs. And so it's kind of just looking at it as a long-term investment and thinking about when this becomes more in demand, we'll have only put out so many of our passport, for instance, and people in years from now might be wanting the benefits that these people are getting because again, we're dropping all these cool exclusives to them. And the only way to get it is to have that particular type of NFT. And I think as people who might've purchased multiple and decide to sell them, there's going to be some sort of resell market, which is something that's popular with NFTs in crypto. (26:31): And for instance, let's just give an example. Let's say we do a limited run of Chris Burkhart NFTs, and it becomes kind of a collector item where there's only so many of them, again, that people have the opportunity after they've purchased to go and resell that later on. So it becomes kind of like this digital trading card that they can do whatever they want, if they want to cash in on the benefits themselves personally, they can, or if they want to resell it later and sell it to someone who missed out on the original sale, that's an opportunity as well.\n\nCole Heilborn (27:04): And I guess that's the part that's so wild to me is that these sort of NFTs can have an extreme amount of value attached to them. And I can't think of a specific example, but I feel like I've read stuff in the news in the last couple of months where things have skyrocketed in value and it blows my mind that this is a thing that is becoming a thing,", "token_estimate": 448, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "25:39", "end_timestamp": "27:04", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "213e3414-382b-4ee7-a4c7-ca5d5739ff5b", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 13, "content": "Ariel Macrae (27:26): But it's all arbitrary, right? I mean, it's like any piece of artwork. If you look at something Andy Warhol created, he only did so many paintings, and an original Andy Warhol could be worth so much money because he gained popularity, but at the time when he was painting soup cans, people probably didn't think it was initially going to be that valuable. So you look at things like that and just have to kind of have this realization that everything is kind of this assignment of our own subjective value that we're going to put on something. And so if you say, I believe that has value because I think this artist is amazing and I want to support them and I want to support their career, then it becomes valuable. And so I think as a community, what we decide has value is really what's going to determine it. I think a huge part of this too is just looking at these artists and athletes and saying, Hey, I really appreciate the content that they put out and I enjoy watching it or looking at it or whatever, and I want to support them so they can continue to put out more of it for my enjoyment. And by purchasing a piece of their artwork through an NFT, I'm helping them continue to do that. You have to think of it as this mutually beneficial piece that you are contributing.\n\nCole Heilborn (28:53): Right? So with the goal being to get people outside, I guess, how do you see this fulfilling that goal? You've talked about if someone bags a peak, they maybe get an NFT. That model kind of reminds me of Strava. You complete a challenge, you get a sticker. I can't remember what they call. So how do you see that fulfilling the goal or the mission of outside Ink?", "token_estimate": 423, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "27:26", "end_timestamp": "28:53", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "4fcc28c4-1c1f-4e82-8512-4453620c1547", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 14, "content": "Ariel Macrae (29:18): Yeah, right. I mean, it's this model of gamification. I mean, that's what our cell phones and all of these digital platforms have trained us to do. It's really playing into that side of our brain that is motivated by these types of rewards. So I think there's this aspect of understanding that not everybody needs that to go outside, but how can we take something that's there? It exists, it's already a part of our universe, and it's only going to continue to be more so and put this kind of positive spin on it. And I think that's where we look at all of these mapping apps in particular. They're the perfect example, like I said, Gaia and TR Forks of how do we take these things that people are already using and try and motivate them to be even more excited to go out and spend that time outside. We have gotten into this space where we're using Fitbits and Apple watches and we want to close our rings, and we're finding ways to use technology to actually motivate physical movement. So that's a huge part of it. And then there's the other piece of that community connection outside too, where there's potential within the Web3 to have these real life experiences tied to the NFTs too, events and things of that nature that will help motivate people to connect with their own local communities as well.\n\nCole Heilborn (30:47): It's funny you mentioned that. So I think about one example that pops into my mind is the idea of using technology to get people outside like Pokemon Go seems like such a great example of how a game, an app motivated tons of people and it still does to get people outside and to get out in their community and walk around and search for Pokemon, which seems like on paper it seems like such a wild idea. Would this really get people outside? But it did. And it seems like there's some similar parallels here.", "token_estimate": 466, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "29:18", "end_timestamp": "30:47", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "0369a08e-e788-4191-b802-545d55cf8555", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 15, "content": "Ariel Macrae (31:21): Definitely. I think we're kind of going for the outside focused version of Pokemon Go in some ways. And I don't think that's a bad comparison because as much as that there's derision about people playing the game and being distracted and being outside, it's still effectively achieved that aspect of getting people outside of their video game platforms indoors and getting them to do it outdoors and getting people to move and getting people active. And again, it's like that same thing. I keep saying the technology's there, it's happening no matter what. So why don't we embrace it and make it positive?\n\nCole Heilborn (32:05): Do you think people want to embrace technology like this?\n\nAriel Macrae (32:08): Not at first. I think we're all looking at these things very skeptically, but I have a strong inkling that in a number of years we will look back on this and it'll seem absurd to us that we didn't adopt it sooner or that it's just becomes such a standard part of life in many ways. There's so much discussion about how Web3 and blockchain technology can just be integrated into so many parts of our life, and I think that's the direction that technology is moving right now, and hopefully we're the company that's figuring out how to make it a bigger part of the outdoor world in a good way.\n\nCole Heilborn (32:48): Yeah, interesting. So a few episodes ago I recorded an episode with Bethany from the North Face, and we talked about Web3 and how they're looking at this landscape and reacting to it. And I'm curious, so I guess I'm aware of you guys and then the north face that are starting to play ball in this arena. What other companies in the industry are also looking at this and trying to figure out what does this mean for us?", "token_estimate": 442, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "31:21", "end_timestamp": "32:48", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "54e050db-75e7-4c67-8b07-227f9ea36a1a", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 16, "content": "Ariel Macrae (33:21): I think a lot more are going to move this direction. The ones that I'm aware of right now, Volcom is another great example of it, and I think retail, they're kind of in general adopting this first because there's a really easy translation to tying in their real product with this abstract digital thing. But Volcom, for instance, offered the stone land NFT, and everybody who purchased gets 50% off for the rest of their life while they own that. And yeah, there's just so many things I think companies are going to move forward and do that tie into this. And I wouldn't be surprised if companies like Strava and other companies that have already kind of stepped into this space of gamifying the outdoors, find ways to tie it in with Web3 as well.\n\nCole Heilborn (34:12): So I'm hoping you can educate me on this. Also. I was reading that the National Park Service came out with something related. Do you know what that is?\n\nAriel Macrae (34:23): They actually, I believe the National Parks Project one was not directly collaborative with the actual US Forest Service national Parks. It was just a project that someone else created that was focused around artwork for the national parks. There might've been a nonprofit donation component, but to my knowledge, I don't think it was actually, and I could be wrong, but I don't think it was actually produced by them.\n\nCole Heilborn (34:49): So as you look towards the future, and if you had to take any wild guesses in terms of where this will take us, what things could be and what sort of opportunities and what do you see?", "token_estimate": 399, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "33:21", "end_timestamp": "34:49", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "3cdf47e8-9740-4322-b7c7-78b99475eeef", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 17, "content": "Ariel Macrae (35:04): Wow, that's a hard question. I'm still learning so much about this space myself, and I'll say that I certainly came into this a little bit skeptical as well, and then just have continued to learn more about it and figure out ways to really tap into all of these different amazing features of this technology. I think we're going to continue to learn more about what the benefits are, what the potential is. I look at things, for instance, I just locally did a challenge on Strava to raise money for reproductive rights by completing a number of miles biking and things of that nature. And I just see so many ways that Web3 can potentially be the way that we do these things moving forward, the way that people are tracking all of their memberships and their subscriptions, and having one centralized wallet login for all of these things that is tied together and can be traded between different apps and utilities and things of that nature. So there's a lot that can be done, and I think that we're all going to learn how that plays into the outdoor space more as it develops.\n\nCole Heilborn (36:25): Sure. So I'm also curious, if you had to guess, what are the top three questions or points of friction that people have about this technology and the outer verse before they become adopters? And how I got to imagine a lot of what you guys are trying to do is just educating people as well. How do you go about doing that?", "token_estimate": 361, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "35:04", "end_timestamp": "36:25", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "2f48f950-dc6e-48c0-b589-c3b054d59a37", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 18, "content": "Ariel Macrae (36:49): Yeah, I mean, I think the number one thing that we get all the time is the questions about the energy usage and whether this is bad for the environment or not. So we talked a lot about that, but I really have spent a lot of time just trying to educate people on that piece. And it's that, and people also think NFTs are a scam, and I understand why. There's definitely been plenty of scams out there and people being fleeced for their money by purchasing these things. But we as a larger legacy brand company outside are backing this and saying, we've put the time in, we've put the research in, we're verifying this, we're putting our names behind it, and we wouldn't do so for something that we thought was going to potentially be a ripoff or take people for their money. This is us putting our entire brand behind this. (37:44): So there's a lot of trying to fight against that stigma there and show people about how this can be a good thing. And I think there's also just this really old school way of thinking, and not using that in an ages term, but just this way of people being resistant to change and not understanding how a non fungible token, which is what NFT translate to actually can have these real life fungible benefits attached to it. And they really trying to get people to think of it less of this piece of digital art that's worthless because it's not actually anything that you can hold onto and say, well, not only does it support the athletes, it supports the nonprofits, it gives you all these digital benefits, but we are tying real world benefits like these gear drops and these tickets and these other things to it. So there is an inherent actual value to it beyond that abstract artistic value as well. So just trying to get people to understand this piece and how all of these creators and just our community as a whole can benefit from it has been an interesting task to take on, and hopefully we're moving in the right direction.", "token_estimate": 496, "speakers": ["Ariel Macrae"], "start_timestamp": "36:49", "end_timestamp": "36:49", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "a38e00a2-5ed3-4e80-9b04-2b2f8eb48e99", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 19, "content": "Cole Heilborn (39:09): Well, and like you've said, it sounds like so much of what could be with this technology has yet to be discovered and how it gets applied and what you might think a year from now looks like. It might be totally different when we actually get there. I guess you guys along this journey, you might discover something amazing and realize there's a whole new world of possibilities that you could tap into.\n\nAriel Macrae (39:34): For sure. We're learning every day about every feature that we can potentially do and partnerships that we can make to improve this and make it even better for our existing holders and our future holders. So I think there's just this kind of aspect where we have to tell people like, Hey, just come on this journey with us. We know it's kind of taking leap of faith in a lot of ways, but we know that eventually this is going to be where things are headed, and by being an early adopter, we're going to give people lots of benefits by hopping in early. And then for everybody else who comes later, they need some more time to figure it out or they need some more time to realize the potential. I hope that does come because the more and more I'm involved with this, the more I do see that it really has so much that we can do moving forward. I'm excited about it.\n\nCole Heilborn (40:25): So thinking about all of this from the marketing department's perspective, why does this matter for folks in the marketing world?\n\nAriel Macrae (40:35): I think for me, being the person that was frequently working with creators and just seeing how many brands are offering exposure as a way of benefit for being involved, it's really just not fair. It wasn't balanced. So that was a huge part of what motivated me to become involved with this project and become excited about it in the first place. And then on the other side of it, there really is just kind of this fun aspect of working in this new digital space and learning how to talk about it and message it and showcase it to an audience that it maybe isn't super familiar with it. So that's been exciting", "token_estimate": 525, "speakers": ["Cole Heilborn", "Ariel Macrae"], "start_timestamp": "39:09", "end_timestamp": "40:35", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "a48dca01-5ed3-4d35-95a2-a3ee6d739087", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 20, "content": "Cole Heilborn (41:16): For a brand who's considering looking into this, investing into it, what's the opportunity for them and from the perspective of the relationship that they can build with their audience, with their customers.\n\nAriel Macrae (41:32): I think it's another way to just build community connection and have people feel like they have a tie in and just a voice in the brand and a voice in what's going on. They're kind of showing direct support. It's almost like buying stock in a project in a sense. So you're really just trying to show people that if they advocate for your brand and they become a part of it, that they also in return are going to get fun benefits back. So I think that there's a lot that people can feel that they're just becoming more involved.\n\nCole Heilborn (42:12): Yeah. Is there a chance that all of this technology could just crash and burn in the future? And why do you believe that that won't happen?", "token_estimate": 236, "speakers": ["Cole Heilborn", "Ariel Macrae"], "start_timestamp": "41:16", "end_timestamp": "42:12", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "8863a606-1c9a-47a4-8be3-3241b1ecbc4f", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 21, "content": "Ariel Macrae (42:22): Yeah, I mean, yeah, sorry, I didn't mean to talk over either. Look at Blackberries. Some of the technology that we used previously, flip Bull and some of that nature technology changes. Some things are not long-term or they're adopted short, and then we've discovered better things, and it certainly could go that way. But I think we've seen over the last number of years that crypto in general is here to stay. There was so much buzz about it in the beginning, and there was so much skepticism about its viability and about its ability to be a legitimate and well adapted thing. And now everybody seems to be investing in some form of crypto or another. My grandparents are asking me about how they buy crypto. All these technologies are constantly going to shift and become outdated. Eventually. We're in this conversation point about web two versus Web3 and how everything's moving this direction and how we're going to have to adapt and shift things to do that. And so I think there's just a time where we will see that full shift happen and it'll become kind of the mass adopted thing, and then eventually, maybe this'll be the thing that becomes passe, et cetera. But I don't think it's going away anytime soon. I think it's here to stay, and I think it's only going to get bigger.\n\nCole Heilborn (43:57): All right. So as a potential adopter of this, could you potentially give away an NFT for someone who completes some outdoor activity but they didn't bring their phone with them?", "token_estimate": 378, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "42:22", "end_timestamp": "43:57", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "e6d06ae9-f6a9-4d2e-8da2-b1f9aa69afdf", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 22, "content": "Ariel Macrae (44:11): I think we're still figuring out how to measure that kind of stuff, and I can't say on the technology side that I am the most knowledgeable person about how that might work, but yeah, I'm not sure what that's going to become. It's funny, I'm seeing stuff on my TikTok and Twitter about people putting microchips under their manicures. I know what all the wearables and the tracking and all of that and how it's going to tie into Web3 moving forward is going to be, that's not my space really, but I think we're going to figure out ways for everybody to adopt this and take it outdoors with them in a way that's easy and doesn't require them to actually actively be looking at their screen while they're doing it.\n\nCole Heilborn (44:50): Sure. If you had to predict at what point in the future will this become more of a common tool or a common platform that people adopt?\n\nAriel Macrae (45:01): I think it's coming quickly. Yeah. Just again, in that amount of short time where in the last couple of years it's gone from being the outlier if you invested in crypto to being a commonplace thing. I think we're getting there fast, and I think adoption of the technology is going to happen pretty quickly in the next couple of years.\n\nCole Heilborn (45:22): Yeah. Very cool. Well, Ariel, this has been a really fun and insightful conversation. I've definitely learned a lot. I feel like I have a lot more to learn. I feel like you've given me some more questions. I need to go Google. If folks want to follow along and learn more, where would you suggest that they go look?\n\nAriel Macrae (45:42): Yeah, so definitely check out all of our socials. We're outside io, Instagram, outside io, Twitter, outside io, et cetera. And then we've got a great Discord channel, which is kind of the up and coming social platform for community building, especially in the NFT and crypto world. And you can find more info@outside.io online.\n\nCole Heilborn (46:04): Okay, great. Is there anything else that you'd want to leave our audience with before we sign off?", "token_estimate": 517, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "44:11", "end_timestamp": "46:04", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "e63d5bfd-c2dd-4d39-ab3c-328275dd1e0c", "episode_id": "335aef4a-ed62-4117-9b78-1dca9959c49a", "cms_item_id": "68225dfc7bb476527f8c4899", "chunk_index": 23, "content": "Ariel Macrae (46:10): Ooh, get outside. Yeah. Whatever you're doing, just make time for it. Take a couple of minutes a day and go for a walk or hike. Take your dog out, whatever it takes to just break away from the screen a little bit and enjoy it.\n\nCole Heilborn (46:24): Okay. Awesome. Well, you heard her. If you're listening to this podcast, you should probably stop. It's convenient because it's about to end. Go outside, go have fun. Ariel folks want to follow along with you personally. Are there any social channels they can go to follow\n\nAriel Macrae (46:37): You? You know what? I spend so much time of my work life on social media that I don't really do it in my personal life because I do want to spend that time outside. So\n\nCole Heilborn (46:46): Good for you.\n\nAriel Macrae (46:46): Yeah.\n\nCole Heilborn (46:49): Awesome. Well, thanks again for taking the time to chat. I'm super excited to see what the future looks like for the outer verse, and I hope that we can stay in touch and maybe revisit this conversation in a few months from now and see how things are developing.\n\nAriel Macrae (47:03): Yeah, me too.\n\nCole Heilborn (47:04): Alright, have a great rest of your day.\n\nAriel Macrae (47:06): Thanks. Bye\n\nCole Heilborn (47:07): Bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 366, "speakers": ["Ariel Macrae", "Cole Heilborn"], "start_timestamp": "46:10", "end_timestamp": "47:07", "podcast_index": 115, "episode_name": "EP 115: Ariel Macrae |The Outerverse | Outside Inc.", "slug": "ep-115", "web_url": "https://www.portsidepro.com/podcast-feed/ep-115", "guest_name": "Ariel Macrae", "guest_title": "Marketing and Social Media Manager for Outside Inc", "categories": [], "short_description": "Ariel Macrae is the Marketing & Social Media Manager for Outside Inc. She has spent over ten years in the outdoor industry, in both service and product marketing roles. She started my career working for ski resorts with a big focus on season pass marketing strategies, transitioned into freelance helping startup outdoor product brands, then started working for ROAM Media 2 years ago. ROAM Media was acquired by Outside Inc. last fall and Ariel has since taken the lead on content marketing for the launch of the new NFT creator marketplace Outside.io.", "podcast_length": "47:29"}, {"id": "91d303de-61ce-4d5e-9df4-b86c654356e0", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 0, "content": "Chris King (00:02): What the problem was was that how do we get all of these items shot in outdoor locations with the budget that we had and so we had become dependent on those outdoor images to sell items. We can't, it's impossible to shoot all these items in different scenes. Is that how can we create a better studio photography experience to showcase these items and then use the photo budget that we have to really showcase the brand versus showing the ins and outs of every single piece that we make?\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Hallborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn, and today I'm sitting down with Chris King. He is the senior director of Brand over at Outdoor Research. Chris, how are you?\n\nChris King (01:15): I'm doing well, Cole, how are you doing?\n\nCole Heilborn (01:17): Doing great, doing great. Excited to be chatting this morning. How are you doing?\n\nChris King (01:22): I'm doing good, man. Just getting the week started and I usually try get in the office a little bit early so I can wrap up the tiny things before the days get going and it's busy times down here at Outdoor Research, so lots of meetings.\n\nCole Heilborn (01:38): And it sounds like you just got back from a couple weeks out of the office on some shoots. How did those go?", "token_estimate": 464, "speakers": ["Chris King", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:38", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "40146489-7b81-48ce-a4dc-161510f63b59", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 1, "content": "Chris King (01:43): They went great. We're capturing our spring 23 collections right now, and I think it's just a really exciting time for outdoor research as the product side of the company has just been crushing it on the design and clothing creation and really developing an amazing collection of apparel pieces that I think are going to really start competing out there, and it's just really excited to shoot that stuff. It looks so good.\n\nCole Heilborn (02:16): Do you always look forward to productions when you get to head out of the office?\n\nChris King (02:20): I do. It's good and bad, right? It's hard to be out of the office as we have everything else going in here on the marketing side of things. And I think things tend to slow when that happens, but as my background has been in production, it's really something that I do look forward to. And as I've been doing it for, gosh, about 13 years now, I'm not behind the camera anymore usually, but I think as when you really start to understand what makes productions tick, you can really take all of that knowledge and make sure that people are excited to be there and the experience is fun and that when you have that stuff, the photos and the video content just come naturally.\n\nCole Heilborn (03:11): Yeah. Well, and that's a great segue into what we're going to be discussing today. We're going to be chatting all about content, content strategy, creating content. And Chris, you've got an pretty incredible background in all of those realms. I'd love if you could just give us kind of the quick history of Chris, where you've been.", "token_estimate": 400, "speakers": ["Chris King", "Cole Heilborn"], "start_timestamp": "01:43", "end_timestamp": "03:11", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "88c79b8c-45bd-480e-b5d1-aef7527399cd", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 2, "content": "Chris King (03:32): Yeah, totally. Let's see. I graduated college in 2008 and kind of came into a wild job market where there weren't a lot of jobs and it was an interesting time. Did some bartending in there, did some marketing for some finance companies, really exciting stuff, but was always kind of interested in cameras and video and never really got into it seriously just because back in oh eight there was more of a barrier to entry. And then I remember Canon started coming out with cameras that you could make look great from a cinematic point of view, the five D mark twos and the T two and all those. And I picked one of those up and just started shooting my friends skiing and started shooting videos of vacations and really kind of learned how to edit and how to shoot content. And from there I was getting pretty tired of doing finance marketing, which as you can guess is as exciting as it sounds. (04:41): I decided to quit and start making small business videos. I think that's a fairly normal thing in today's world, but back in oh eight you kind of had to go to a larger production company and spend a lot of money to do that, whereas I was pitching myself and my road mic and my Cannon camera set up and I'd kind of make these two to three minute narrative pieces. And my first kind of big client was Woodenville Whiskey company, which was kind of getting their start also in Woodville and who doesn't like bourbon? And I got to tell a lot of cool stories with those guys and kind of just really showcasing that craft and showcasing how awesome the Pacific Northwest is and kind of a dream gig for someone like myself at that time. I look back at those videos now and they're pretty cringe to watch, but it was a great foray into that world. (05:40): And from there started a production company that I titled travels through Images because my young self thought that the longest name ever would be great. And so that stuck with me until, let's see, that was in 2010 ish all the way through 2019 when I traveled all over the world to shoot video content, was doing a lot of auto and travel and outdoor and really started to grow this production company. And the coolest part about it was getting to know all the creatives in my area and working with like-minded people and really understanding what made productions or good productions go. And it's really, I'd love to say it's all about the talent behind the camera, but it's really about the support that you have and can you put that talent in a great space with nothing else to think about besides grabbing the story or grabbing the subject. (06:47): And I think I started to realize that where my talents really lied, and again, don't get me wrong, I still love shooting photography and video to this day, but I think producing these shoots is what really kind of came to me naturally, making sure that we were going on location, that we had great places to stay and that all the talent had good dinners and making sure that there was also an experience that went with the shoot, not just waking up and grinding for 14 hours a day because that can get a little bit long in the tooth. And so really had a fun time doing that. And I would say that it was the highest of highs and the lowest to lows, kind of when you're running your own production company, you sign big contracts, there's nothing better, but there were obviously those times when rent's due and you had to find new clients and sometimes you had to go film stuff you didn't want to film. (07:46): You did a lot of real estate videos back in those days just to keep the money coming in the door. So yeah, I had my daughter in 2017 and then my wife and I kind of decided that it would be good for me to be around rather than traveling four or five months a year. And I'd kind reached the point in the production space where I was hitting the goals that I wanted to hit when I stepped out. I think I could have gone forever, but I also wanted to maybe try living life, not working 24 hours a day and just see what that felt like. So I took a job@rover.com, which was a, it's kind of the Uber for dog walking in Seattle. If you have a dog, you probably know about it. And they were looking for someone to stand up an internal content studio there and start producing everything from commercials all the way down to social media content. (08:47): And it was definitely below where I was, but I knew that to enter the corporate world, I had to go grind it out and take a job that was lower than the money I was making at the time. But I really wanted something that was going to challenge me and humble me a little bit because it's really easy to go to amazing locations and shoot good content just because working with the best athletes in the coolest places and shooting dogs is a boy. That's that's a whole nother level. You're living by the dogs rules at that point, but it was crazy going in for, you're kind of used to working 50, 60 hours a week and you enter into a corporate space and it's a totally different mentality. And it really allowed me to, the first few months were kind of interesting where I was, I think my manager was like, Hey, you need to slow down a little bit. (09:44): You're going too fast. And I was just kind of used to working at the pace that I've been for the last few years. And so it really allowed me to slow down, be able to help more at home, kind of enjoy those years when my daughter was growing up, while also learning how to work with people that were not the people that I'd been with for the last eight years. And that was a really cool experience, and I knew that after a couple of years there that I'd kind of tapped out a little bit and there was no room for me to grow. But I'll never forget it. I might've learned more in those two years about working with people than I did my entire years of production, just from a totally different standpoint. (10:29): An ad agency in Seattle called Bamboo had a job out for a creative director, and they specialize in paid social ads and kind of the growth aspect of marketing. And for those that they're listening that don't know this would be paying for your paid ads that you see when you're running the thumb at night. Those ads come through Instagram or Facebook or TikTok or LinkedIn or whatever there, and again, another world that I was familiar with, but one that I wasn't immersed in, I was kind of making the content for these teams not really in it and understanding the analytics for that. And so I remember to this day, it was March, let's see, February the end of February of 2020, and I decided to take the job and it was definitely a tough decision to make because I was going in to manage a team of eight people there. (11:24): Let's see, yeah, seven, eight people at Bamboo, and definitely taking more of a managerial role and fully exiting the creative space, which I was also excited about because I really wanted to see if I could be the coach and be the supportive system there. And I know that that sometimes has been harder than doing the actual work. And so took that job, went to Hawaii for a couple weeks, and then COVID was just getting going during that time and it was crazy. Bamboo let me know that they were going full remote and they would be sending a computer to my house and Rover proceeded to let half of their staff go, and half of that staff probably would've been me since I was kind of an on the ground office guy working remotely. It would only last for so long. So I don't know if it was a blessing in disguise or it was the right move to make, but it put me into this crazy working from home situation that we all went through. (12:36): So won't spend too much time there, but I definitely thrive and am able to be the most successful person I can be if I'm around people. And it was a very tough lesson for me to be coaching and leading from a computer screen and never meeting these people in person, and especially in a space that I was very new to and creating content for the paid social space, your three to 15 second world is really different. Quality goes out the window. How do we fish hook people? And coming from a quality heavy background, it was pretty nuts and it really forced me to kind of change the way I looked at things. And also it was just intriguing because now we're looking at what is becoming the normal side of content these days. It's interesting talking to those that are younger than me who don't watch hour long ski movies anymore and who don't watch hour long mountain bike movies anymore just because the attention spans just aren't there. (13:42): And so, yeah, it's one of those reasons why I would happily go without Facebook these days. And so got into that and worked with this amazing group of people over there. It was a very young company with great leadership, and it gave me this whole new skillset of just understanding people and how do you get people to do the things you want them to do without asking 'em and how do you lead that way? And the other thing that was taken away was on location shoots. We could no longer do that anymore for the first part of COVID. And so now all of a sudden we're helping people shoot UGC content, which was a term that was pretty light back then, but became a very familiar one during that space. And so it was kind of a work from home, be the pep talker, making sure the budget was right, and really just kind of driving the ship. (14:47): And it was probably one of the coolest learning experiences I've ever had and will forever be thankful for it. But a year into that job, I can't remember where I saw it or who sent it to me. I think someone sent it to me on LinkedIn, but there was a recruiting company that was hiring for a creative director kind of leadership role in the outdoor space and in Seattle. So I think living in Seattle, you have an idea of who those companies are going to be, and I had a feeling it was, but I was kind of wondering, I feel like a lot of those jobs are REI these days, but went through the first screening meeting with Tammy who's a recruiter at the Nodo group, awesome conversation. And she let me know that it was outdoor research, which I hadn't been super ingrained in what or was doing to me or was the company that made pants for ski patrollers and those that were at the top of the skin track every morning in the backcountry. (15:47): And that was kind of my foray. And I had friends that used, and I always knew them to be the quality, quality kind of higher price gear with not a lot of colors function first over fashion. But again, I think when you are an outdoors driven person, whether it's skiing or mountain biking or trail running or whatever, hiking, backpacking, those jobs don't come along very often and definitely a dream job for me. And so went through a bit of a rigorous interview stage, I think it was 12 interviews with or yeah, and I could tell they were taking it really seriously and they were restructuring an entire executive team and marketing was one of those last items. And the challenge there was, Hey, we've been through the COVID washing machine too. How do we get people back to the office? How do we reinvigorate people? How do we get a company that's made such strides in apparel design and production and kind of now bring in the marketing side of it and the content side because that was the side that was struggling a little bit. So yeah, it's been a little over a year since then.", "token_estimate": 2878, "speakers": ["Chris King"], "start_timestamp": "03:32", "end_timestamp": "03:32", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "93b5e0de-6577-4a0f-a052-265535aa9f63", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 3, "content": "Cole Heilborn (17:07): Awesome. And it sounds like it's been a busy, fun year.\n\nChris King (17:11): Super busy, fun year. It's kind of taking every experience I've had the past 10 years and really using my Rolodex as much as I can and bringing in people that I've met throughout the creative world and taking a very small marketing team and giving them as much as I can, the tools that they need to be successful in. So whether we've done a lot of things, we've kind of finished going through a rebrand that had started before I got here, new mission statements, new content strategies, new social media strategies, really trying to give people the imagery and the content and the literature that or is no longer kind of the top of the little guys, but now we're kind of the bottom of the big guys these days as far as our competition goes. And it's a 40-year-old Seattle company and I feel like not a lot of people in Seattle know that. (18:13): And so including myself, I didn't know that they'd been around for 40 years and having that history is pretty special and really the best part of the job. I think when you get into a marketing position, and I would assume that most people on the podcast and yourself, we've all had to market things that we either did not think were that great or were not interested in. And that is the biggest challenge. But the thing about or is that the product man, it speaks for itself and if you can get that product in people's hands, it does the selling on its own. And so now what we're trying to do is making sure that we're selling that image that we want to be portraying. And the biggest question that comes from the outside is who is or and what is. And so we're now trying to carve our own lane in the outdoor industry and through content production and showing people what we're about. That's kind of the challenge these days.", "token_estimate": 469, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "17:07", "end_timestamp": "17:11", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "c5479ce4-db0e-4896-b3af-6a9529af90ae", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 4, "content": "Cole Heilborn (19:12): That's kind of wild to think because I guess being up here in Bellingham, not far away from Seattle, I've always heard of or, and so the fact that you guys are that people don't know who or is really interesting. And so let's dive in a little deeper. So that's one of the challenges that you are working on and content strategy is a piece of the puzzle in terms of how you're trying to accomplish this. So I'm trying to figure out where we start because\n\nChris King (19:42): Yeah, totally. There's a lot of directions.\n\nCole Heilborn (19:45): Totally. So is that kind of the premise? Was that the challenge that you were stepping into?", "token_estimate": 165, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "19:12", "end_timestamp": "19:45", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "01e9ef90-9f25-4eb7-a07c-d8a74dadbde2", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 5, "content": "Chris King (19:52): Yeah, so I mean I can break it down pretty down to the request really when I got here, we have what some may look at is a decent sized photo budget and content budget. We do not have the content and photo budgets of our competitors these days of where we want to be at. And that's part of growing. And so I think the challenge for me right off the bat is how do I take this budget and really exceed the current expectations of the content strategy that we're had? And I think that that's a real challenge and I think it's been a challenge for others before me here. And what I had to offer here is that one, I try not to do it a lot, but I was able to shoot content if we needed quick things. But I knew I had a lot of friends in the industry that I've worked with for a long time that were at a high level that charged fair normal day rates. (21:00): We're not the outdoor industry company that's going to trade somebody gear for work. I really, it's important to me having been on the other side that people and contractors who work for or working for four and feel that it's a fair rate because I need these people to come back and I want to make sure that we just really set a standard there. And I think before I got here, there was a bit of a lack in production knowledge, and I don't think it was the end goal of like, Hey, we need this content to be great. It's just that I think having that Rolodex really helped me a lot and I just have some awesome friends that have become important to me for sure. But what was going on is that with the small photo budget, the team here would shoot really, really good content, but the budget didn't run very far. (21:56): And one thing about or that a lot of people don't know is that we've got an insane amount of products in the 300 range and all the way down to boxers and all the way up to $700 Gore-Tex shells. And with a 20 capsule unit photo budget would be no problem. You could really focus on experiences and you could make sure all those things were captured. But what the problem was was that how do we get all of these items shot in outdoor locations with the budget that we had and those images were really helping the e-comm, our website really looked great. And so we had become dependent on those outdoor images to sell items. And so we kind of had a few different options. And what the change I've been doing is that after figuring out that, hey, we can't, it's impossible to shoot all these items in different scenes, is that how can we create a better studio photography experience to showcase these items and then use the photo budget that we have to really showcase experience and then our top of line items and really show the brand versus showing the ins and outs of every single piece that we make. (23:16): And that was kind of the first deal was fix the content capture. And so that's what we've definitely been working on the past year.", "token_estimate": 733, "speakers": ["Chris King"], "start_timestamp": "19:52", "end_timestamp": "19:52", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "c5f2125c-2bbd-4716-b8e2-b3daaba69530", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 6, "content": "Cole Heilborn (23:26): So I think that budget dilemma that you're describing is a dilemma that I got to imagine everyone faces regardless of the scale that you're operating on, whether you're a one person boutique company or we use the example all the time, Patagonia, it always seems like you could use more and there's never enough money to spread throughout all of the different types of content that you want to create. I don't know from the production side when you were doing that, how would you experience that with clients?", "token_estimate": 133, "speakers": ["Cole Heilborn"], "start_timestamp": "23:26", "end_timestamp": "23:26", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "e0617eaa-3b87-48d1-b45c-31dad241070e", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 7, "content": "Chris King (23:57): Totally. I mean I think, man, you can make such amazing content these days with little amounts of money. Where extra money comes in is once you have the piece of equipment and you have the talent behind the camera, now you're just building a support system. We have our ambassador team that we often use as our models for athletes or for showing people in athletic environments. And then sometimes we have to use professional models. And when you build, the more amount of people on set is the more money. And so around the DP or around the photographer, you can have stylist, you can have hair and makeup, you can have assistance and you can rent expensive equipment. You can rent crazy stabilizers and cable cans. And as you know, that train never ends, right? Do we want to have nice cinema lenses? And then the money just goes higher and higher and higher and all of a sudden you can get to 10 or $15,000 a day on a set really, really fast. (25:10): And there's nothing more fun than having a large budget and being able to take a chef's knife and improve the little things around the DP or the photographer and also give them the comfort that they have the support, which whenever I had that support and I was shooting, it's like you can totally zone out and not even have to worry how the models look or have to worry, worry about dumping cards or have to worry that stuff is set up and ready to go. And that is when you have that kind of comforting feel like that, I think you can really do your best work. And so what I tried to do was make sure that I could now use my talents on set and be on set. I'm technically, I'm a salaried employee, so we're not paying a day rate for me, but knowing what a photographer and videographer usually needed, I wanted to be that assistant in the back and maybe we hire another assistant also that's also helping. (26:07): And I was just trying to trim the fat as much as possible and knowing that we could start at a base level because there were low expectations when I got here, we could just start ground bottom and really focus on a good location and making sure that the clothes were representing the use case that they were in. And so as simple as it sounds, making sure rain jackets were shot in the rain, simple stuff like that. And using the amazing space we have around here in the Pacific Northwest and not traveling a ton allowed me to kind of fine tune these shoots, though they're still expensive. The end of a three day shoot with a small crew was still, and models and ambassadors is still costing 20 to 30 grand at the end of the day, usually around 10,000 bucks a day. And so that sounds like an insane amount of money, but to shoot the amount of items that we were shooting and the experiences that we were trying to do, when you're competing with the North faces and the Patagonia and those people, that isn't the top. And so that was really the challenge coming in here and something that I think we did a really good job at and the internal marketing team here at or is awesome and people just want to see the brand flourish, which is great. And it's been a huge support since I've been here.", "token_estimate": 795, "speakers": ["Chris King"], "start_timestamp": "23:57", "end_timestamp": "23:57", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "4a1c5354-4166-47c6-a0f3-5398cf2aae5b", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 8, "content": "Cole Heilborn (27:30): So it sounds like in order to figure out how to stretch the dollars and figure out where they should best be allocated, did you first start by designing the entire strategy and figuring out what's important or what can we do or what can be shot on a studio? How did you walk me through that strategy side of it?\n\nChris King (27:53): Yeah, I remember we were a couple of weeks in and it was late, it was July. And so spring 22 had not been shot yet and we need to have spring summer deliverables by usually October 1st because we launched in March and it was a bad fire season, so there was smoke everywhere in the Pacific Northwest. And I remember working with a colleague of mine and saying, all right, show me the budget. Let's see the Excel sheet. And I could immediately tell right off the bat that there was large amounts of money being spent on things that weren't necessary. And it's a really tough position to be in as a new head of marketing is that there are a lot of vendors that work with the company for a long time, and I've been on the other side of this myself that usually when your connect, that's a marketing at a company leaves, oftentimes they bring their people in. (29:01): And now I'm on the other side of that having to have conversations with photographers and videographers that we plain and simple to capture the content that we need. We can't afford you. And as much as I think your photography is amazing, we need to do five shoots this summer, not one. And we can't blow our entire budget on one or two photo shoots. We had to spread it out as much as we could. And so figuring out, okay, now where can we go? What's cheap for us to get to? Where do we need to go? And at that time, climbing was a big part of the seasonal capture that we were doing. So I remember the first shoot we went on was to Smith Rock down in Bend and it kind of gave me an idea of what the expectations were because everyone down there had been on a photo shoot with or before, a lot of our ambassadors were there, people were helping that were part of or, and it really kind let me know that the productions that or was used to was 10 to 15 people going around an outdoor location and definitely more of a, it's hard. (30:08): It's hard that many people to get the contents herding cats. And it definitely let me know that we needed to downsize as much as possible and again, spread the money around as much as we could. We needed to have four person teams without a huge travel or send gear to people that were in those locations to make sure that we could get a variety of content. And so it was a really fast moment and there were some definite wins that summer, but it was also crazy. You're just drinking from the fire hose trying to fix all the things that the people above you expect. So yeah, just kind looking at the spreadsheet and starting there,", "token_estimate": 722, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "27:30", "end_timestamp": "27:53", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "bfa22ff4-3bc6-4825-96e6-89b1bef3579e", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 9, "content": "Cole Heilborn (30:52): How do you recommend, this is a very general question, but how do you recommend folks figure out actually what to spend their dollars on?\n\nChris King (31:02): That is a great question.\n\nCole Heilborn (31:04): And I guess when I say spend, I am imagining if you're going to hire a photographer and you have all of this content that you ideally want to shoot with this photographer, how do you actually decide what is worth spending the money on? Because I'm assuming because you can't afford it all.", "token_estimate": 131, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "30:52", "end_timestamp": "31:04", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "79e296f0-1537-4465-9496-809156427774", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 10, "content": "Chris King (31:24): Yes. So I think from a priority perspective when I'm designing a shoot is that I start with our crew first and really at, or we like to use a variety of content creators so that the content isn't all the same, which is also a challenge in itself too. And thankfully again, got some good connects as I just noticed as I was perusing your podcast, a few people that have been on here before we work with and I think like, okay, we got our team, we have, can we afford to have video as well as photo? And we start with that team and who needs assistance? Do we need an assistant for both photo and video? Can we have one assistant for both? Can I come and help with that stuff? And then from there we got to pick the location. And so we are really trying to figure out as a brand where we want to show up in our imagery and we're Pacific Northwest through and through, but we also want to expand. (32:30): And so I think we're going to shoot most of our stuff up in the Pacific Northwest, but we're also going to venture to other places too because we want to make sure that in order for us to expand to the east coast, we need to have some east coast imagery. Maybe it's not all of it, but there has to be some, right? And looking at the full season, where is that large travel budget going to come in and what can we do at home? And so going back to the individual, shoot, something that's very important to me, which I think is maybe not for others because we've all been on shoots where we're sleeping at janky motels with four to a room. I want to make sure that everyone has a great place to sleep and sometimes their own bedroom if possible, or a great bunk situation and that everyone is well fed. (33:20): And again, there's an experience beyond the shoe. I've just learned that if we're in a beautiful place and we don't have to worry about going to get not a great sleep at the end of the night and not have a, not a party per se, but just a fun, relax time to get regenerated for the next day, I want to make sure that's a great situation. So I think I tend to spend more on the travel side of it than others do, but that's important to me for my crew and making sure that there, like I said, there's a great experience in there. So we'll do the travel and then from there we get to figure out the talent situation and are we bringing ambassadors on the shoot? Do we need models? Build that out. And then usually with the extra that's left is okay, what extra gear can we bring with us to take the production to the next level? (34:17): What do we need to rent? Are we going to rent some nicer cinema lenses? Are we going to rent stabilizers? Are we going to rent rain machines? Are we going to rent a 12 by 12 scrimm to really set up a beautiful setting that isn't blown out by the sun? Just that little stuff that adds up really quick when you're on a one week shoot. And so that's kind of how I look at it. And oftentimes, hey, we might just be on a trail and trying to hit the best light and we don't have any extra grip and that's it, but we have to still get that content. And some shoots I have more budget than others, but yeah, that's kind of the formula that I go with.", "token_estimate": 802, "speakers": ["Chris King"], "start_timestamp": "31:24", "end_timestamp": "31:24", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "c9bb04a7-5e04-4720-ad38-a786722590d9", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 11, "content": "Cole Heilborn (34:54): Gotcha. What about, similar question but from a different perspective now. What about for brands who maybe don't have as much production experience as yourself, and maybe it sounds like you're kind of playing, you are a producer, you are playing producer for these shoots, for brands where they aren't familiar with producing something and let's say they're bringing in a producer to help them bring a shoot together. How do they decide of all the different shoots that they could pick from and work on throughout the year, maybe they want to do a product piece, they want to do a story piece, maybe they want to create a bunch of social contents and they're looking at bringing in a producer and a team to shoot all of that. How do they decide from that brand level what's worth investing in?", "token_estimate": 204, "speakers": ["Cole Heilborn"], "start_timestamp": "34:54", "end_timestamp": "34:54", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "8688d56a-f00f-4c7b-823d-43ce72b28900", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 12, "content": "Chris King (35:42): Huge. I think that it's tough if you don't have the general background in which of those tools can be the most valuable. I remember earlier on in my career, I was trying to be the DP and the producer at the same time, and I remember the first time that I paid for a producer to come on a shoot and my mind was completely blown because all of a sudden I didn't have to coach models, I didn't have to talk with, we were doing a casino shoot, I didn't have to work with the people at the casino, I just could focus on what I was doing. And from then on, it became an absolute no brainer for me. And so having a good producer can be expensive, but the value rings through. It's kind of like you get a great photographer and nothing against the people that create content whatsoever. (36:42): I think you can get a good photographer and that person can run a whole shoot no problem. But for those larger scale shoots, a producer really makes that person shine. It's kind of putting nice speakers on your really nice area. And so I think if that experience isn't, there's a lot of really good companies up here in the Pacific Northwest that do produce shoots. We were using a production company up here that was before I was here, gosh, I can't remember the name, but they were helping put all these shoots together because there really wasn't a great internal person to help with that. And it is an expense for sure, but I think it helps get your shoot off the ground level and then the people, the internal people the company can focus on, alright, here's what this gear needs to look like and what are the assets that we need and we can just focus on that part where the producer can kind of wrangle everything else.\n\nCole Heilborn (37:38): Yeah, interesting. So what about now feels like the right time to invest in some of that story focused stuff?", "token_estimate": 467, "speakers": ["Chris King", "Cole Heilborn"], "start_timestamp": "35:42", "end_timestamp": "37:38", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "d153afca-37e5-4ac4-bc12-8e02b27790c1", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 13, "content": "Chris King (37:48): So in order to get to the place where we could start pushing the brand awareness and pushing outdoor research instead of just marketing single pieces of apparel, the product had to be in a great place. And so as I mentioned before, the product really needs to be in a great place. For those that don't know in larger apparel brands, or at least here, it takes about three years from an inception of a product design prototypes, building the fit and really getting the product shot from a marketing perspective and then going into a retail location takes about three years or about that time ago, brought in a new team on the product side who's just been crushing it and really bringing the clothing to a very respectable place where I think in the past or is very much or has been technical before or technical or function before fashion. (38:57): And that left us with pieces that would protect you in the outdoors no matter what. And again, there's only a select amount of people that need apparel like that and how could we keep that same mentality but also design pieces that someone who'd never, that was hiking for the first time or wanted a great down jacket or soft shell or raincoat to wear to and from the office, how could you apply that design towards that group as well? Because again, if you're growing a brand at the place you want it to be, we have to sell beyond the niche customer group. And so the clothing and the clothing design has really gotten to a place where people felt comfortable now pushing the brand because of what we had to offer. And not only is our stuff extremely well made and designed, it's starting to just look really awesome. (39:58): That was the first step of that process. The second step once we had that is that making sure that our internal, our seasonal photography and our seasonal content capture to use on web and social media and for any out of home stuff was also on point as well. And I think then at that space, and once I kind of had a good formula going there, air came the harder question because I think I know the production world really well and I know how to get a product from holding it in my hand to up on the website. I know that formula great, but now it's the request came in from our president of, okay, let's go build this brand and let's let people know who we are. And so we are going to get going on a brand awareness campaign in the start of October, kind of when it gets a little colder. We do have a ton of winter outerwear that we're pushing in a big way this year, but that now it's time to start testing some other platforms beyond just Facebook and Instagram.", "token_estimate": 665, "speakers": ["Chris King"], "start_timestamp": "37:48", "end_timestamp": "37:48", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "e53cb48c-8d2b-4d73-92fe-a2a28cef42d7", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 14, "content": "Cole Heilborn (41:10): Yeah, interesting. I was reading a statistic and it said since 2018 to 2021, the amount of video watched per person per week has almost doubled from about nine hours a week to now 18 hours per week. I'm just curious to hear your reaction.\n\nChris King (41:31): I mean, yeah, it makes sense, right? We were at home a lot and I think, gosh, I know that we definitely increased our video watching that was for sure. And whether that was watching more movies and shows on Netflix or using YouTube as a tool to work on home projects, we never took part in content has become more than just kind of a veg out situation. And a great example of that is on our YouTube channel, we have a ton of tutorial videos that we've produced in the past and everything from, Hey, here's how to put skins on your skis all the way, how to rig your climbing gear, what goes in your back country backpack, stuff that the team before I got here was working on. And man, the viewership of those videos is, I could tell you some of the stats on that is crazy, like 40 to 60 hours per week on these three minute videos is just you see people that wanted to go outside and wanted to learn new things. And I think from a content strategy, yes, of course we were maybe watching six seasons of Peaky Blinders in a week, but I think also there was this education piece that's always been there, but I think it came in because a lot of people started doing new things. When COVID started, the outdoor spaces exploded. You couldn't, with the supply chain and the amount of people joining the sport, you couldn't find a bike for a few years there. (43:16): And I think people wanted to know how to do things. They wanted to exceed their talent levels. And you saw just this explosion of camping and hiking and mountain biking and backcountry skiing. And fortunately for us, we are in a great place for that and noticed that our certain pieces of our content started to just increase. But that's the name of the game these days.", "token_estimate": 504, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "41:10", "end_timestamp": "41:31", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "ffa69097-c660-485c-9577-0500f209fab0", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 15, "content": "Cole Heilborn (43:40): So if content, if video consumption has doubled, I mean, I guess a simple assumption would be that brands output of video has doubled. And then would that also mean, am I wrong to believe that then budgets have also doubled?\n\nChris King (44:06): We are trying to be very conservative right now because, and I doubt we're the only one, we're kind of wondering if this push to the outdoors is going to last. And I think the really good thing about COVID is that on one side there was a major mental health explosion about not being able to ever really leave your job because you were just at home all the time and living the at-home life. And it's, it was hard to turn it off there for a while. But the other side of it is that you had this like, okay, maybe I'll get up early, maybe my list of responsibilities, maybe I don't need eight hours to get that done during the day. (44:55): I think for a long time in offices, the two o'clock to five o'clock hour was spent surfing social media sometimes. And if you read, you can read a lot of studies that tell you that time of the day is your least productive. And I think you saw, at least I know for myself, a lot of people get outside during that time. It was the safe place to go. And so from a content perspective, we needed more content, we needed more video showcasing our products so people would know what to buy. We needed more storytelling, we needed more internal video that talked about our product technologies, more tutorial videos, and we've really been trying to do our best there. But no, the budget has kind of stayed the same because we really want to make sure that we've definitely fruited off of this outdoor push, but we want to make sure that this keeps going. And I think if you were a logical person, people are going back to work and we may be looking at a recession here in the coming years, the writing's on the wall, and we want to make sure that we can still put out what we're doing in kind of a frugal way, but also make sure that the partners that we're working with we're being fair with all of them and also keeping the quality of that content in a good place rather than trying to create more content where the quality lapses a little bit.", "token_estimate": 562, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "43:40", "end_timestamp": "44:06", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "46f008e5-e968-4e63-824f-40f24862391c", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 16, "content": "Cole Heilborn (46:25): Yeah. Gotcha. I'm just kind of going through some rapid fire questions. So podcasts, we're obviously in a podcast format. I'm curious, how do you see podcasts in the future of content strategy? I mean, just chatting with a lot of marketing folks through this medium, it definitely seems like something that brands are interested in producing or being a part of in a sponsor format, something like that. What do you think happening?\n\nChris King (47:00): Again, two paths. You produce your own internal podcasts, some brands are doing that and then, or you can sponsor a podcast. And I think coming from a production world, not a podcast world, producing a podcast is no easy job and not a job that someone who's already doing production can go and just handle, right? It's like, I think in the early days of social media, there were not social media people. It was, Hey, can you manage our Facebook or something like that. And now we have dedicated social media people. And so I think right now for us, an internal podcast is probably out of the question. And I think what it would take us to grow that as you know, got to put in that time and really make sure that you have a niche. One of the reasons why I like your podcast a lot is I really want to know what other people in the industry are doing and how they're getting through challenging problems. And I think you have a great niche in that. I think we could probably come up with something, but it would be tough. So we're actually going to try sponsoring a few podcasts this season as a bit of a test and see if there is an ROI on that. And we are doing this brand awareness campaign and we want to add a couple of different mediums to it. And I'm really curious, and I think, have you worked with sponsors on your podcast before?", "token_estimate": 453, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "46:25", "end_timestamp": "47:00", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "a29b8640-5474-4d5d-8c8b-3dc9e5b4c30c", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 17, "content": "Cole Heilborn (48:34): Short answer, no. It's something that we have entertained, but I think the value that we provide that we could provide to a potential sponsor is very niche and very limited just because our audience size is very niche and very focused. So it's something that, I've had a few conversations with brands, but we've never run an ad to this point. Not to say that we wouldn't be against it, but I think we just got to find the right fit for our show.\n\nChris King (49:06): Exactly. And I definitely wonder the same things myself, and I think the easiest form of advertising is having a call to action with an easy route to a purchase. And I think if you're in the niche of the podcast and you are about what that podcast host is talking about and they recommend a product in a non-car salesman way, you can have success there. But I don't think it's ever going to trump the success that a paid social ad is going to, only because you can click and purchase where a podcast, you have to stop listening, find a purchase portal and go from there. I mean, that's a great customer to have right there because usually that's going to probably be a repeat purchase customer. But it's an interesting space and I'm really curious to see what comes back from that personally.\n\nCole Heilborn (50:03): So when you think about metrics, data seems to be everything as we inform our content and the types of content that we produce. I know this is kind of a general question, but what sort of metrics are you looking at that helps inform your content strategy decisions?", "token_estimate": 393, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "48:34", "end_timestamp": "50:03", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "4b241894-e53e-4a1b-99b1-78dfca880b34", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 18, "content": "Chris King (50:22): Well, obviously we're really focused on the metrics that come in from, I would say meta, Facebook and Instagram. We really like to see our roas, which is our return on ad spend. We really focus on our conversions. Cost per million CPMs are also great also, and this is me kind of playing devil's advocate, we're getting a lot of those metrics from meta and we know that what we're putting forth does turn into conversions, but it is kind of something that sticks in the back of your head of, Hey, the person that I'm paying the money to, or the company I'm paying the money to is also giving me my metrics. And we can get third party metrics from Google Analytics also, but it's kind of a wild space out there. And we do our best and we have a really good paid social team that puts forth an understandable monthly report because you can get lost in those metrics. And so the metrics that I'm kind of looking at is where are we growing a lot? And YouTube metrics are pretty crazy because it's longer time watched on your brand than an ad, but again, is more of a brand awareness ad. And it's definitely the old school way of marketing is not. There was a time where we would spend money on marketing and we wouldn't have all the metrics that we do now. And so Instagram is great for purchases that are made directly from the platform. (52:02): Really one of our fastest growing channels right now is LinkedIn, which is crazy. But we grow at a faster rate on LinkedIn than any of our brands right now. And I do think that it's helped us kind of be a little bit more known in the workspace and has helped us attract really good talent the past few years. So we're trying to figure out how to use that a bit more. But this fall we are going to kind of go away from the metrics a little bit. We're going to do some billboards, we're going to do YouTube, which has metrics, but not put as much focus on Facebook and Instagram. And I'm just really curious to see how that tests out. Obviously when we're going to report all this, we have to use as many metrics as we can because there is comfort in knowing what's working and what isn't.", "token_estimate": 538, "speakers": ["Chris King"], "start_timestamp": "50:22", "end_timestamp": "50:22", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "87e93119-920c-4a2a-80c2-1fd013a3da82", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 19, "content": "Cole Heilborn (52:57): Sure. Yeah. Well, we've talked about a lot of different facets today, Chris. I'm curious though, if, what does the future look like for content creation? What's your hunch?\n\nChris King (53:12): Man, an interesting one, because we have content that gets hundreds of thousands of views that's shot with an iPhone and on Instagram reels, which is crazy to me and also an amazing way to get more eyes on the brand. And the one thing I keep coming back to is how do we get more viewers to our brand reels on Instagram are a great way to do that, but then how do we also tell our brand story? And I think we're going to have, we already have it now, but there are two different pieces of content because whenever you're showcasing your brand or telling your brand story, I think you want that quality to be top notch. And that's kind of the, Hey, whenever we're working with new partners, new content partners, photographers, videographers, usually the last part of that conversation before we talk an actual project is, can I see your portfolio? (54:20): I want to see what you have to offer. Send me some examples of relatable work. And that's when a content creator is going to put forward their best piece. But they might've been doing some tutorial videos on their Instagram stories. They might've done reels about behind the scenes of the recent shoot that they did. That supporting content, I think really acts like the fish hook in getting new eyes onto your brand. And so right now, it's obviously been proven in more ways than one that you don't need to have the nicest imagery to get a purchase or conversion. But I do think when you are telling your brand story, you want to put forward the best pieces of content that you can get. And so where it used to be, that used to be the only thing. I think we now are realizing that we can shoot content that's really fast on iPhones because people really want to see what goes on behind the scenes, or they want to learn how to do something in the outdoors and they don't really need a cinematic approach to that. And that to me is one of the coolest parts of content is that we're now sharing all this information through video, and then when we really need to represent the brand in the best way, we want to put forward the best content that we can make.", "token_estimate": 583, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "52:57", "end_timestamp": "53:12", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "d542b34c-1bd2-464f-8089-d8f4b6405004", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 20, "content": "Cole Heilborn (55:34): Yeah, it's an interesting time for sure.\n\nChris King (55:37): Yeah.\n\nCole Heilborn (55:38): But I feel like we always kind of say that, which seems kind of like a cop out as a phrase. Everything is an interesting time,\n\nChris King (55:47): Very much so, especially given the fact that this content surge wasn't really happening 12 years ago. It was just getting going. So I think it's going to level out a little more as we kind of realize what content begins to work and what doesn't. But I do think there's going to be an ever-changing social aspect to content and how we view it and what do we need for some stuff and what do we need for others. And I think that if you can have some balance there, I think it really shows what you're trying to do very well. Well,\n\nCole Heilborn (56:22): Chris, I want to thank you for taking the time to chat today. If folks want to follow along with outdoor research or with you personally, is there a place you'd want to send folks?\n\nChris King (56:33): Yeah, totally. So outdoor research on Instagram is a great place, and that's just outdoor research. We were also building up our TikTok right now, and that's going to have a lot more of your UGC based content. That's also outdoor research as well. Yeah, we've started to get into some fun projects over there and got a great new organic social producer that's working on that. And then me personally, probably, I don't seem to be as active anymore these days, but my Instagram is Chris King, PNW. I might find some behind the scenes stuff on there as well.", "token_estimate": 394, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "55:34", "end_timestamp": "56:33", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "8d5c03e8-2f1b-4dbc-9a17-0a04671d6e07", "episode_id": "c948a978-a1e3-4026-aff6-3b3e3ad678b0", "cms_item_id": "68225dfc7bb476527f8c489c", "chunk_index": 21, "content": "Cole Heilborn (57:13): Awesome. Well, it sounds like we should keep an eye on you and the next foreseeable future of, or sounds like a lot of exciting things are happening and who knows, who knows where some of these trends and where some of this content will go. But I appreciate you sharing and giving us a deep dive into your perspective on some of these topics. I guess there's no one right answer, and I think what I've noticed from this conversation with you is that you can always create more content. There's always more to be made, but figuring out what to spend it on, what to focus on is the hard part. And if you can figure that out and then you can actually go out and make the content, chances are the success and the return on that content will be worthwhile.\n\nChris King (57:58): Dude, totally agree. I think as long as you're open to trying new things and staying humble and realizing that maybe you don't have all the answers, you can kind of keep moving at that pace.\n\nCole Heilborn (58:11): Awesome. Well, I think that's a great life motto, a great way to wrap up today's episode. Chris, thank you again. Have an awesome day, and we'll see you soon.\n\nChris King (58:21): Yeah, buddy.\n\nCole Heilborn (58:24): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 359, "speakers": ["Cole Heilborn", "Chris King"], "start_timestamp": "57:13", "end_timestamp": "58:24", "podcast_index": 116, "episode_name": "EP 116: Chris King | What IS a Content Strategy? | Outdoor Research", "slug": "ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "web_url": "https://www.portsidepro.com/podcast-feed/ep-116-chris-king-what-is-a-content-strategy-outdoor-research", "guest_name": "Chris King", "guest_title": "Brand Director", "categories": ["creative"], "short_description": "Chris King is the Brand Director at Outdoor Research. He’s had many different roles in his career, from marketing manager at a finance company to starting his own production company to creative director at an ad agency. And now, he’s landed at Outdoor Research, which he says is his dream job.", "podcast_length": "58:43"}, {"id": "89174c17-f1ba-4899-a269-7380e9b826f5", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 0, "content": "Dax Myers (00:04): Creating as broad of an awareness funnel that we can, and that's ultimately how we're going to shift the paradigm, is creating that awareness that the stuff is gnarly, it's nasty, it there have been incremental changes. We go from short chain floral carbons and ski wax, which it's still a fluorinated wax, but instead of breaking down, never, it'll break down at some point.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Hoborne and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Port Side Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo. Today I'm sitting down with Dax Myers. He's the director of marketing over at Mountain Flow. Dax, how are you\n\nDax Myers (01:14): Doing? Very well. Stoked to be here.\n\nCole Heilborn (01:16): Yeah, thanks for joining us. How is your day going?\n\nDax Myers (01:20): It's solid so far. We're starting to kind of transition out of the summer heat. We've got kind of the fall. Cool. Settling in. It's been a really lovely morning in the Crystal River Valley.\n\nCole Heilborn (01:31): Yeah. Where are you calling in from?\n\nDax Myers (01:34): So I am technically in Carbondale, Colorado, but I'm closer to Redstone, so 14 miles outside of Carbondale, only about a mile outside of Redstone.", "token_estimate": 435, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "00:04", "end_timestamp": "01:34", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "60daa378-0581-490b-b084-d474a849752c", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 1, "content": "Cole Heilborn (01:43): Okay, gotcha. Right on. So this is a complete side thought, but when we first got connected, I noticed your hat, and I think it's the same hat you're wearing today. It's a high above mountain bike hat, and I would be really curious to see. I don't know what I want to see, but I just feel like there's something super interesting about people who wear hats with logos on them, and it's different than wearing a sweatshirt or a jacket with a logo. I think it says something very different about the person. I don't know, I'm curious what your thoughts are.\n\nDax Myers (02:15): I think that I would agree with you that there is definitely something different with hat branding. For me, it's more about the fit of the hat and the branding comes kind of second. And so when we were up in Bellingham, we were next to, we were at the tuneup event, we were next to the high above tent, and the fact that the hat fit really well was the reason why it gets so much usage. But that said, it is a very cool logo. They've got very clean branding over there\n\nCole Heilborn (02:44): And the whole, I never know how to do this depending on the hat. Do you tuck the ears in or do you tuck the ears out?\n\nDax Myers (02:51): Great question. Especially as somebody with pointy long ears. I'm typically a leave them out. I've actually had former bosses that have been like, will you tuck your ears in? Come on. So I'm camp out. But\n\nCole Heilborn (03:07): Yeah, same. It's so uncomfortable to have your ears jammed inside a hat. I feel like it takes away from your ability to actually hear things. Well, completely off tangent, but Dax, thanks for joining us today. So I got to say, I only knew, I feel like half of your guys' story when we were first introduced. I didn't know that you were in the bike space, but I've heard of you in the ski world. For folks who maybe aren't familiar, could you give us the quick introduction on Mountain Flow and who you guys are?", "token_estimate": 493, "speakers": ["Cole Heilborn", "Dax Myers"], "start_timestamp": "01:43", "end_timestamp": "03:07", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "5a24ee8a-5766-4bbe-a5d3-75b34c7951b8", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 2, "content": "Dax Myers (03:38): Yeah, absolutely. So Mountain Flow, we've been around since 2016, and we started in the ski wax space, really recognizing the imperative really to make a cleaner ski wax. So much of the consumables in the ski and bike industries are made with really nasty, gnarly chemicals. And so that was kind of the original impetus for mountain Flow and really just kind of leapt used that to really kind of get to a point of reach a performance threshold while completely redesigning how ski wax is made. So we use plant-based formula. It's biodegradable, it's non-toxic, no petroleum ever. And then we've taken that same ethos to all of the bike lines. And we are a certified B Corp. We actually just recer it this year. And so we put thought into every single aspect of production, and that includes the product itself, but it also includes the packaging. (04:47): And so we use post-consumer plastic in just about every single thing we put out. And then we also use our bike wash, for example, utilizes, it's a cardboard kind of hybrid container. And the way that it works is it's a thinner plastic reservoir wrapped in cardboard that uses 70% less plastic than a traditional plastic bottle. And so realistically, we kind of have our toes dipped in multiple spaces right now. And again, this is all based on recognizing the gaps in the bike and ski industry, consumables world, and seeing if we can do it better. And so we're in the process right now of launching recycled aluminum ski poles, which a hundred percent out of the realm of consumables, but it's something that isn't really being done right now in the industry. And the initial measurements are showing that recycled aluminum utilizes about 95% less carbon emissions than a virgin aluminum ski pole. (05:49): And so really trying to use the sustainability narrative to, I guess, let me rephrase that. We're focusing mostly on quality. We want to create quality goods because you can be as sustainable as you want, and if your products don't work, then nobody is going to care. And so we're walking that line. And from a marketing perspective, we definitely lean performance first, sustainability second. We would much rather somebody be like, wow, this chain loop is incredible. And then find out later that, so yeah, that's kind of the long and short of mountain flow. No, petroleum is kind of like the overarching ethos through every single product. And then, yeah, plant-based biodegradable.", "token_estimate": 617, "speakers": ["Dax Myers"], "start_timestamp": "03:38", "end_timestamp": "03:38", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "7a84a9f1-ce32-4a7c-889f-c635ac886c58", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 3, "content": "Cole Heilborn (06:45): So I've always had the assumption that the nastier, the ski wax or the nastier the chain lube, the better it has to be for the performance factor. How does that work out? What plants are these derived from?\n\nDax Myers (07:04): So the ski wax that we use, at least in our standard hot wax line, we have a race line and then we have a hot wax line. So just our standard wax. It's actually an amalgamation of succulents. And we've taken the hydrophobic qualities of the several succulents that we use and have basically applied that same sort of chemical reaction to the ski wax. And then when it comes to our race wax, where really you kind of notice number one, racers are finicky. Number two, wax makes all the difference. I mean, that's the surface area that's touching the snow. And so we use a, it's a ceramic nano powder that's actually been licensed from the Department of Defense. And the whole intent is to mimic the properties of a fluorinated wax. And we have a few athletes that have podium at the Olympics on that. We have a couple of X Games athletes that have podium. (08:04): And so at least as far as the quality narrative goes, it works every bit as well as a fluorinated wax. And of course I'm biased here, but I'm willing to die on that hill. And so realistically, for us, especially in the race world, it's getting people to take the step of just try it. And so one of the strategies that we've adopted is we've worked with teams to supply them with practice wax. And so go out, give it a try, ski some gates, let us know what you think. We have the narratives from Alexander killed. It is one of our athletes, and if it works for kilda, it'll likely work for you. But that subjectivity is hard to overcome sometimes. Our whole thing is we just want people to try it. And we're not out here making any crazy assertions. The best thing that we can hear is that you notice no difference between a fluorinated wax and hour wax or a petroleum-based chain loop and R chain loop. At the end of the day, they just have to work.", "token_estimate": 516, "speakers": ["Cole Heilborn", "Dax Myers"], "start_timestamp": "06:45", "end_timestamp": "07:04", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "c2165e9a-75c0-4c94-8e1a-1ed1c74700d6", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 4, "content": "Cole Heilborn (09:10): So I've never really thought about the sustainability factor of either of those products. Are there any studies that have been done that show the impact of petroleum-based products on the ski hill or on the trails?\n\nDax Myers (09:23): There are, yeah. There's a study, I can't remember the university that it came out of, but it's up in the northeast. And what they did is they looked at race venues, and so they looked at Alpine race and Nordic race venues and really high concentration of fluorinated wax usage in those types of venues. And ultimately what they found is the PFAS chemicals, the forever chemicals that don't break down the long chain fluorocarbons, finding those not only in the snowpack, they're finding them actually residual traces of those in the soil as well. And so the study then further goes on to say that A, they're actually finding bioaccumulation in human blood of some of these forever chemicals. And so in addition to being, when you're waxing your skis and you're breathing this stuff in, it's carcinogenic and the fact that it's accumulating in human blood is also one of those things that pretty nasty, pretty gnarly. I'm not a doctor. I don't know the long-term health ramifications for that, but I would guess that it's not great.\n\nCole Heilborn (10:32): Yeah, I feel like no one wants that in their body. Another fact that you mentioned to me when we first connected, that blows my mind. Lemme know if I got this right, but in a week's amount of time, a human will consume a credit card amount of plastic. Is that right?\n\nDax Myers (10:47): That's true. Actually. I have an Instagram video teed up on the mountain flow Instagram that's going to go up today and really driving home that fact. But that's something that I didn't know. But yeah, over the course of a week, we all on average consume a credit card's worth of plastic. And so when you compound that with all of the forever chemicals and everything else that's happening, it's kind of a toxic cocktail that we're all sort of unwittingly consuming.", "token_estimate": 517, "speakers": ["Cole Heilborn", "Dax Myers"], "start_timestamp": "09:10", "end_timestamp": "10:47", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "b3205039-9361-41ed-bb7e-2625aad9040e", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 5, "content": "Cole Heilborn (11:19): Yeah. Wow. Yeah, that's disgusting. And obviously ski wax and chain lube are a very, very small piece of that pie, but the fact that it all adds up is, I dunno, that's pretty disturbing.\n\nDax Myers (11:33): It is. And one thing about ski wax and bike products specifically are the areas with which you get to on your skis and on your bike, and ultimately everything that you put on your skis and everything that you put on your bike is going to shed and come off in the environment. And so it's ultimately, one thing that's really I've kind of grappled with is just ultimately the dispersion of these chemicals. Again, back to that kind of unwitting sort of mindset that you're just out dispersing these nasty harmful chemicals and the places that you ultimately love the most.\n\nCole Heilborn (12:11): Yeah, yeah. Riding through a creek crossing seems a little, yeah, I got to think twice about that. If I've just lubed up my chain and it's nice and nice and greasy. I love the background. It's just super interesting where you guys came from. Was the goal from the beginning of the company to be sustainable and was that the intention?\n\nDax Myers (12:32): Yes. Yes, it was. Yeah. So Peter, the founder, basically started with recognizing the gap here and seeing if it could be done better. And so when shaping and molding the company, it was always based in the sustainability side of things. How can we do this with the least amount of impact rather, and want to minimize our impact, but we also want to make something that works.", "token_estimate": 389, "speakers": ["Cole Heilborn", "Dax Myers"], "start_timestamp": "11:19", "end_timestamp": "12:32", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "36077d86-d30a-4875-927c-94064a5bc385", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 6, "content": "Cole Heilborn (13:05): Yeah, interesting. Well, one of the things that you mentioned to me and where we're going to kind of take our conversation today is talking about the challenges of, well, trying to market something such as ski wax or chain lube. And you mentioned that in that industry, you guys are kind of a commodity. You go to a store, you go onto Amazon, and there's hundreds of choices and they all look the same, and they all claim different performance benefits. And that's kind of what we're going to get into is how do you do that? How do you think about marketing something that maybe people don't think about when they're, maybe they're just looking at price when they're making the decision. Obviously you guys have a really interesting backstory and there's some unique things I think we can dig in here. But I guess from the beginning, Dax, what's kind of the challenge that you see and that you deal with day to day as the director of marketing when it comes to your position in the commodity market?", "token_estimate": 256, "speakers": ["Cole Heilborn"], "start_timestamp": "13:05", "end_timestamp": "13:05", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "74b1a81d-2618-4a51-942a-14bf37b7286a", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 7, "content": "Dax Myers (14:01): Well, it's ultimately awareness. We mentioned that ski lube, or excuse me, ski wax and bike lube are commodities in the space. There's a pretty low chance that you're going to store hop looking for a specific brand. Granted, that is a little bit less true in the ski wax world, especially if you're on the race side of things. But when it comes to bike lube, I mean 13 to 17 bucks a bottle, you're just going to get whatever's closest, whatever's most convenient. And so creating an awareness and really kind of focusing on that top of funnel awareness is kind of where we've really focused. And you mentioned this, we do have a good story, which definitely is an asset for us and really helps with the narrative storytelling when it comes to cultivating that awareness. But it's a challenge, especially when there are multiple steps to maintaining and even achieving awareness. (15:11): And ultimately, the first question, without doubt, whether I'm at an event or at a trade show, first question that I'm asked is, does it work? And usually it's like, yeah, bring your bike over, we'll loop it up for you. Tell us, let us know what you think. I run the info account, the howdy@mountainflow.com, and I handle just any inquiry that comes in and anybody that reaches out, I send, reach out to me directly if you have any questions. I'm genuinely curious to know your thoughts. And so we have a lot, especially with how things have been changing, especially with the millennials coming of age, there's a ton of studies out there that say that especially in the millennial space, we're more likely to support brands that sort of take a stand on things. And so we have had people that have come up to the tent or reached out via email and say things like, I saw that you had me there. (16:12): Why don't you tell me about your products? And so that's certainly a hook, but it's not really the hook. And so realistically, to kind of continue the phishing analogy with a hook, you've got the trouble hook that's like three different, I guess hooks. We're really employing even more than that. We have five to six different awareness campaigns because ultimately we just want people to know about us. And then after you create that initial awareness, we have that really strong narrative that we can sort of, I don't want to say fall back on, but then we can utilize as people kind of move through the funnel there,", "token_estimate": 607, "speakers": ["Dax Myers"], "start_timestamp": "14:01", "end_timestamp": "14:01", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "f1deb80e-7be6-4926-84cc-35862c29560e", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 8, "content": "Cole Heilborn (16:59): What takes a commodity product and what turns it into a product that has a brand behind it that someone will drive across town to go pick up because they can't find it at the nearest store?\n\nDax Myers (17:13): Well, I think that the story really is huge there, but it's not just any sort of generic brand story in my mind. People are willing, once they're aware of not only mountain flow, but once they're also aware of the harmful effects of some of the other petroleum based products out there, that's ultimately what's driving the need to maybe jump to a few stores to find something that's not as kind of gnarly. But that said, a story only goes so far. And so we want to create that. We want people coming in, we want them to be aware of us, but we want them coming back because they love our products and because they work for them. And so it's kind of a nice little sprinkle on the end there. If the products happen to be sustainably made produced, we're a B Corp. And so every aspect of the supply chain is under examination during our recert. And so knowing that you're supporting a company that supports every touch point is helpful. But again, if the product doesn't work,\n\nCole Heilborn (18:31): Yeah, what does it matter? Yeah, so I was thinking about, as we were talking about this episode, and I was doing some prep for it, I was doing some research on commodities and just trying to understand the general landscape. And there's a lot of articles that popped up about how do you market a commodity? And in a lot of the examples they were talking about, they're companies like water companies or they use the example of steel or grain or things that no one really thinks about, but they're the building blocks to everything else that we all end up using. And I'm curious, looking at the industry as a whole, the outdoor industry, what products do you see being products that are commodity products and which products are things that you personally view as very heavily branded or things that have a loyal following?", "token_estimate": 514, "speakers": ["Cole Heilborn", "Dax Myers"], "start_timestamp": "16:59", "end_timestamp": "18:31", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "3cf623eb-ddd6-4a36-953e-620f75841dc9", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 9, "content": "Dax Myers (19:40): So ultimately, the consumables world of both industries is really where I see the most commoditization when it comes to the strictest definition of the word. You could argue, and I've even, excuse me, I finished up grad school last year, and I feel like it depends on how cynical I'm feeling, I guess, throughout the day. But there's so many things out there that you could make the argument that are commoditized these days when it comes to ski technology. You could make the argument that while there is a degree of commoditization, there's only so much innovation that you can make in a pair of skis. There are also so many different ways to differentiate a pair of skis, whether it's just true blue branding or the mechanics of the ski itself. And so it's really in what we're using, and I guess that's sort of vague. So it's really ultimately the consumable side of things, the ski wax, sunscreen, chapstick, that sort of thing. And so I guess a lot of these things that I just mentioned are really more industry adjacent. I was kind of just walking through a ski shop in my mind as I was pointing out products like Chapstick sunscreen, but I'll drive across the state for a pair of skis. If it's the pair of skis that I want, I'll drive across the country for a bike. If it's the bike that I want prior to working for Mountain Flow, I wouldn't have gone across the street for a bottle of chain lube.\n\nCole Heilborn (21:30): Right? Yeah. So why is that?", "token_estimate": 370, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "19:40", "end_timestamp": "21:30", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "ff7112d0-e1d9-4805-81df-4b2ffd564275", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 10, "content": "Dax Myers (21:35): I think for me personally, number one, it was kind of just a lack of education on chain lubes not really that exciting of a product at the end of the day. And it was just one of those things where it was notice that my chain was a bit sticky. I need something to help it go in. This is what's on the shelf, this is what I'm going to get. And then ultimately, oh, well, maybe I'll get a pair of socks too, or something like that. But yeah, I think it's just one thing that we've kind of been talking about at Mountain Flow recently is just, it's just like a lack of sex appeal when it comes to ski wax and chain loop. It's just not the most exciting part of the kit. It's essential, but there are so many options out there. I mean, I feel like I learn about a new bike lube company every single day. And so the market is so saturated that it ultimately just boils down to convenience. Let's closest. I really like the shop, and the shop carries chain lube, so I'm more supporting the shop, less supporting the lube company.\n\nCole Heilborn (22:44): Sure. Yeah. I mean, I guess I'm thinking about it from the automobile industry. Everyone cares. Well, most people care what sort of car that they drive. Most of those people probably don't care what type of oil goes into their car so long as that it works and that it doesn't destroy their engine. I mean, it sounds like it's basically the exact same scenario that you guys face. You're integral to the function and the sport and the enjoyment of it, but you're kind of thought about last or the night before you head up on the hill.\n\nDax Myers (23:16): Yeah, absolutely. And at least for me personally, even marrying into a race family, oh no, I forgot to wax my skis, and I'm sort of viewed as a pariah for the day. What? You don't wax your skis every single time you go skiing. And yeah, again, prior to working for Mountain Flow, I mean if I wax my skis three, four times in a season, I mean that was what, a year.", "token_estimate": 496, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "21:35", "end_timestamp": "23:16", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "5028a5b5-e012-480f-906a-9fa89d6aef3b", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 11, "content": "Cole Heilborn (23:42): Yeah. So you mentioned that a lot of consumables for people are commoditized. And then I was thinking about if I was walking through a ski shop and looking at all the things, what are the things, how would I split those products up into those two camps? And the consumables was really interesting and I was thinking about, and eventually I got to the part in the store where they have food and energy bars and chew and gummies and things like that. And that was like, oh, people, when you get to the things that you ingest, at least in that part of the store, people are really particular about their consumables. So there's something different going on there in the consumer's mind about the things they're actually putting in their body, which is ironic of the whole plastic thing versus something like ski wax.", "token_estimate": 209, "speakers": ["Cole Heilborn"], "start_timestamp": "23:42", "end_timestamp": "23:42", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "88bfc802-992c-413a-85e8-f4118c032423", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 12, "content": "Dax Myers (24:32): Yeah, that's a great point. Didn't even really think about the food side of things, but then I started to think about all of my mountain bike friends and all of my ski friends and how particular everybody is on what goes into their body. And I guess it's pretty easy to something if it tastes good versus yeah, it's going on your bike, you wipe your hands off afterwards, and then you just really, I don't really think about it even working for Mountainville, throw some wax on and just go for a ride. So, which I guess really sort of segues into just creating as broad of an awareness funnel that we can, and that's ultimately how we're going to shift the paradigm is creating that awareness that the stuff is gnarly, it's nasty. There have been incremental changes. We go from short chain fluorocarbons and ski wax, which they're, it's still a fluorinated wax, but instead of breaking down, never, it'll break down at some point. (25:44): And so there have been a lot of things, FIS has really led the charge on banning fluorinated waxes. But again, they actually just moved the goalposts back again this year just because they don't have a solid sort of testing methodology. And they were getting false positives when they would test people's skis. And so I think it's the third or fourth year that that's happened. And ultimately, when it comes to just the general conversation, it's been great because it's been centering people's, it's been creating awareness on a topic that ultimately just has kind of been overlooked for a long time. But when you put things on just like an honor system, you have some people that are going to take that step based on this level of awareness that they just gained. And then you have some people that are just going to do what they've always done. (26:38): And it's great that more people are coming over to the side of recognizing that we're not just nothing that we do exist in a bubble. Everything kind of has a ripple effect in ramifications, whether it be environmental or really anything. And so I think that that's the biggest hurdle in this space is getting there. But when it comes to articulating the narrative, one thing that's kind of nice, at least from a marketing standpoint is there are really no rules. And I think that that's evidenced switching over out of the ski and bike industries, but still very much so a commodity that's evidenced in the gold standard case study, at least in my mind, in liquid death. And as far as creating a conversation, I mean, that brand can do no wrong, and some of the stuff that they do might be totally off the wall to me. But I mean, here I am talking about it.", "token_estimate": 669, "speakers": ["Dax Myers"], "start_timestamp": "24:32", "end_timestamp": "24:32", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "46c53f92-573d-4454-9646-0d77e8b46d0c", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 13, "content": "Cole Heilborn (27:47): So it's super funny you mentioned them because just earlier this week or last week, I was interviewing Steven Nielsen, their VP of indoctrination, and if folks haven't listened to the episode, by the time Dax is out, I'd highly recommend you go check it out because Dax brings up a great point. Liquid Death has totally taken something as basic as water and turned it into this cult following of a brand. So it's obviously, it's very possible. And as you say, there's no rules. You can get creative with it. So I'm curious for you guys when you say there's no rules. So what have you been trying? It sounds like awareness, and as you said, the top of the funnel is super important. What does that look like for you guys?", "token_estimate": 186, "speakers": ["Cole Heilborn"], "start_timestamp": "27:47", "end_timestamp": "27:47", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "c67f8c11-4168-4811-93b3-638a1ee0a42f", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 14, "content": "Dax Myers (28:35): Well, for us using Liquid Death as a case study, they lean in really hard to the punk and metal scene. And that aesthetic just is 100% their brand identity, and it really works for us. So our founder, Peter Arlene, incredibly articulate and just really well-spoken guy, but also just maintains an air of just goofiness. He's just a really solid, but really just like goofy, lanky guy. We've leaned in really hard to just some previous, in my opinion, it just really kind of leans into Peter's personality. And so we've been working really hard on humor and we've released, granted, we're not going anywhere nearly as viral as liquid death. It seems like everything they put on Instagram goes bananas these days. But one campaign that we had recent localized success for us was we've created a persona for Peter. He is wearing cutoff jean shorts, cowboy boots, like a flannel cutoff shirt. We've got some shots of him putting on leather work gloves. And kind of like the whole point of the story though is he rides his bike over to the gas pump and pulls out the pump and then holds it over his drive train. And the thought being, you wouldn't put gas on your drive train, why would you put petroleum products on your bike? (30:19): And so really leaning into the soft, humorous side of things to get across those more. It's not necessarily life and death, but it's certainly a more serious message than the feel of the video would. It's not serious. We're not coming out with PSAs and whatnot. I mean, we are, but we try to be funny.\n\nCole Heilborn (30:42): Yeah. And how has that been received?\n\nDax Myers (30:44): That's been really well received. As I mentioned, we haven't gone viral or anything like that, but in our sphere we've received a lot of positive impact. And so we have some really fun stuff in the mix. Really excited to just continue to articulate that story utilizing this persona, creating just a level of brand recognition around Peter and the caricature that we've created for him. And then using that to leapfrog our message across to people.", "token_estimate": 521, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "28:35", "end_timestamp": "30:44", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "309d3dd4-6cc6-4e34-8741-0a7b9feaf5bd", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 15, "content": "Cole Heilborn (31:20): Is a lot of the awareness that you guys are trying to drum up, is that through these types of short, creative, funny videos, or what are some other avenues that you're also exploring?\n\nDax Myers (31:33): So on the more serious side of things, we have a white paper in the works because ultimately we want to get as granular as possible. And given our short format attention span world that we live in right now, we Instagram, TikTok, art, really the venues for that. And so one thing, it's been a slow process, but putting together just a white paper that would be ultimately articulated on LinkedIn or something like that. We also, Peter travels around to, we do panel discussions. We're working with the, it's the, I want to get it right, it's the O Rec office, so it's the Office of Recreation for Colorado. So they have been doing a thing, it's like a tour, and they go around to different rural communities and there, there's new money coming in, and they talk about how we can just strengthen these communities through the lens of the outdoor industry. (32:32): And so as a local business owner in a rural mountain town, that fits in well. And so Peter is able to go and participate in these panel discussions, and that's getting the word out in a really genuine, less humorous way. And so ultimately for us, we just want to have our basis covered. We want everything. We want to be funny. If we had a post that went viral, that would be incredible. I think that's, especially in the social side of thing, that's what we're all striving for, but maintaining kind of like a duality there that we are a serious brand, that we are tackling a serious problem and our products work. I dunno how many times I'm going to say that, but\n\nCole Heilborn (33:22): So do you feel like if you can get the products in hand, get it in people's hands, they can test it out, they can prove that it works. Once you've opened up that awareness and you've gotten the, I guess, how many people, is that even a number? How many people do you want to become aware of the company?", "token_estimate": 521, "speakers": ["Cole Heilborn", "Dax Myers"], "start_timestamp": "31:20", "end_timestamp": "33:22", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "95d65e9e-0309-454d-b6f5-8d7ab0412141", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 16, "content": "Dax Myers (33:42): I mean, I haven't really thought about an exact number. I mean, as many people as possible. I would love every single human being in the United States to be aware of Mountain Flow, and that's what we're working towards. But we don't really have any set KPIs or set metrics that we're working towards there. It's just every single day bringing on more people. And like you mentioned too, that's really our bread and butter. We can put out funny videos till the cows come home, but ultimately, we want people to try our products. And so we have a pretty robust pro team. We have a really robust ambassador team, and all of that is just, we're going to send you out a kit, let us know what you think about it. Don't post anything that's not genuine. If you like it and it works, then we'll discuss. Do a post for us, do whatever you'd like to do that's in your own space. But if you don't like it, tell us why you don't like it. And we'll honestly take that feedback to heart.\n\nCole Heilborn (34:47): Have you heard of the company called Purple Pillow?\n\nDax Myers (34:51): I don't think so.\n\nCole Heilborn (34:55): I feel like they first became a thing on Kickstarter, and they were this funky pillow that had this, I don't even know what sort of technology. If you look it up, you might recognize it, but it's got this gel rubbery look and it's purple.\n\nDax Myers (35:16): Oh, okay. Yeah,\n\nCole Heilborn (35:18): Yeah. You're looking at it right now.\n\nDax Myers (35:19): Yeah, I just pulled it up. Yeah. Wait, did they make mattresses too?", "token_estimate": 389, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "33:42", "end_timestamp": "35:19", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "e0abf7a1-099b-4df4-971b-3036e4c242f4", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 17, "content": "Cole Heilborn (35:23): Yes. So I think they started with the pillow, and then they moved over to the mattress. And I don't know entirely their story, but you're talking about humor and trying to make fun ads that people enjoy and hopefully have some viral aspect to 'em. Thinking about products that are commodity products, like a Pillow to me, is very much a commodity. I think it was one of their Kickstarter videos, they leaned super heavy into the creative of their product launch piece on Kickstarter, and it went viral, and it was incredible. And I think that's led to them making this mattress. But I feel like there's so much opportunity there with these kind of rare, I'll say, obscure products that maybe people don't think about, but they come out with this amazing messaging and oftentimes a funny video, and it just takes, everyone isn't expecting it, and that's what makes it even more fun like a pillow. How boring is a pillow.", "token_estimate": 236, "speakers": ["Cole Heilborn"], "start_timestamp": "35:23", "end_timestamp": "35:23", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "8e687cb8-e103-4c84-ae63-20ca1fc70bad", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 18, "content": "Dax Myers (36:29): Yeah, that's a great point. And one thing that we've had some success in, and when it comes to measuring a degree of virality as a result of this, it's possible, but relatively tough to connect the dots, at least for what I'm about to say. But we were on Shark Tank, and so yeah, so Peter was able to get up. We actually, spoiler alert, secured funding from two of the Sharks, and ultimately was able to get up on stage present mountain Flow, but also in just the way that Peter operates. I mean, he was able to bring you so much kind of charisma and just, I don't know. Peter's got a very unique blend of being well-spoken and also a level, a degree of understated charisma. And it worked really well with the Sharks. It also worked really well as far as creating awareness. I get emails every day that are like, Hey, I saw you on Shark Tank. And so that's been something that's been really a big boost for us. (37:37): Yeah, granted, we haven't leveraged that as much as probably we could have I, but again, we're walking a line between authenticity and while also trying to be funny. And one thing that I should mention too is that we've got, even for people who buy our products, we've got a really robust, if you don't like it, send it back to us. No questions asked type of thing. And that's just one thing that I wanted to mention too, that we ultimately just want to just try it, let us know. And some of our formulas have undergone a couple of generations of improvements based on feedback from consumers like that.\n\nCole Heilborn (38:22): That's cool. Yeah. That's awesome that you're taking it and improving upon the feedback. So we're slowly running out of time, but I guess one more question for you or maybe to think about. So you mentioned there's this awareness piece that you're working on. It sounds like you guys are making great progress with what will it take for once the awareness is you feel like it's well saturated, what will it take for Mountain Flow to become that product that I'll drive across town to go pick up? Because I love it so much?", "token_estimate": 523, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "36:29", "end_timestamp": "38:22", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "9fdf3d56-f47d-4e68-bf99-fc19cc9060b6", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 19, "content": "Dax Myers (38:57): That's a great question. And ultimately, I think that we will kind of cross that threshold when, I mean, I guess as I kind of think through the mechanics of it all, we have so many balls up in the air that we're continually pushing forward. And this narrative is, like you said, being saturated as much as we can as a result of our social media presence, our ambassadors, our influencer stuff. I'm not really sure when that click is actually going to happen, whether you see, well, Kilda uses it, so that's good enough for me. Or one of our athletes is Simmy Hamilton, and he's a former, I think three time Olympic Nordic skier, and he's also just been crushing it on his bike lately now. So I think that there's a degree of, personally, I'm susceptible to that type of stuff. If it works for them, it'll likely work for me. I'll give it a shot, or I respect this athlete. (40:14): I guess one of the avenues being roped in by something that was really funny that got you thinking about your chain lube, that's also something that at least for me personally, would rope me in at least to give it a shot. And so I'm not really sure. I think that it's a multi-pronged sort of answer there, and which is why every single marketer out there, we're working every single angle that we can. When something has good traction, we will pursue that for a while, but we can't forget about all of the other kind of balls in the air as well.\n\nCole Heilborn (40:52): Yeah. Awesome. Well, Dax, if folks want to follow along with you or with Mountain Flow, is there a place people can go to connect?", "token_estimate": 401, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "38:57", "end_timestamp": "40:52", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "77bd303a-c11b-4519-8ee7-e4b55d17ed91", "episode_id": "c9e68a61-0fb5-440b-a765-0cbbd05235f6", "cms_item_id": "68225dfc7bb476527f8c489b", "chunk_index": 20, "content": "Dax Myers (41:01): Yeah, absolutely. On Instagram, we are, oh goodness, I want to get it right. Yeah, so we're Mountain Flow Eco Wax on Instagram, we are Mountain Flow, ew, on TikTok. We have a Facebook presence as well. We produce, we've got a mailing list. We've got anybody who signs up for our email list gets 10% off. And then trying to think what other stuff we have going on. We have our in-person events, it's the Rise event happening down in Arkansas, and we're going to be on a panel down there, and it's all about just sustainable products. And anyways, yeah, there's a number of ways that you can reach us, where we're around. I mean, even shoot us an email, howdy@mountainflow.com.\n\nCole Heilborn (41:48): Okay, awesome. Is there anything you want to leave our audience with before we sign off for the day?\n\nDax Myers (41:54): Not really. I really just love the opportunity to talk about Mountain Flow, kind of talk about the level of disruption that we're striving towards, and yeah, it's been just a really great experience. I really appreciate it, Cole.\n\nCole Heilborn (42:09): Yeah. Well, thank you. Thank you for sharing about a part of the industry that I have never really considered, and I think I'll pay a little more attention to next time I head to the store, especially as we're getting into ski season here. And I look forward to seeing what you guys come up with in the future. And I look forward to seeing you on the shelf here in Bellingham if you aren't already.\n\nDax Myers (42:30): Yeah, off the top. I know that we're in one shop in Bellingham, but I know that we're also in discussions with more, so I'll keep you posted.\n\nCole Heilborn (42:38): Okay, cool. Well, Dax, thanks again. Have a great rest of your day.\n\nDax Myers (42:42): Likewise. Thank you so much, Paul.\n\nCole Heilborn (42:44): See you. Alright, bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 515, "speakers": ["Dax Myers", "Cole Heilborn"], "start_timestamp": "41:01", "end_timestamp": "42:44", "podcast_index": 119, "episode_name": "EP 119: Marketing a Commodity | Dax Myers | MountainFLOW eco-wax", "slug": "ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "web_url": "https://www.portsidepro.com/podcast-feed/ep-119-marketing-a-commodity-dax-myers-mountainflow-eco-wax", "guest_name": "Dax Myers", "guest_title": null, "categories": [], "short_description": "Dax Myers has worked in ski travel for over a decade. When COVID shut down travel in 2020, he was laid off right as I started grad school. He used that time to make a big huge pivot into the product side of the outdoor industry. His current role entails handling all of the marketing efforts and strategy for mountainFLOW.", "podcast_length": "38:21"}, {"id": "7214e0d8-4b82-4294-b1df-eb0755b86dc9", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 0, "content": "Kris Hampton (00:02): It is so hard to not get distracted from what your original goal is. I have to remind myself every single day, this is why I'm doing this. This is the goal of this thing. Don't get distracted down these rabbit holes because I love rabbit holes, Cole. I love going down rabbit holes and learning new things, but I've only got so much room and so much growth potential. I have to focus on the things that are my actual goals.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo. Today I'm sitting down with Chris Hampton. He is a climbing coach. He's also the host of the Power Company Climbing podcast. Chris, how are you?\n\nKris Hampton (01:18): I am great, Cole. Thanks for having me on here.\n\nCole Heilborn (01:21): Yeah, thanks for being here. You've been around the block a few times with the whole podcast thing, huh?\n\nKris Hampton (01:26): I've done a few of these. Yeah.\n\nCole Heilborn (01:29): Well, I'm super excited we could be chatting today. Where are you calling in from?\n\nKris Hampton (01:33): I'm in Lander, Wyoming, standing in my office. My wife and newborn are downstairs, so you may hear little bits of newborn noise down there, and I think my office manager will be getting here soon, but she's used to this and going to be very quiet.", "token_estimate": 473, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:33", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "77a04886-7207-48d0-a095-a5022a6df00d", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 1, "content": "Cole Heilborn (01:53): So I was doing a little bit of internet stalking before this conversation and I was looking up Lander and it looks like it's right kind of in the northwest corner ish of Wyoming. And I noticed that you wrote a poem about Lander and the climbing, local climbing crags, it sounds like, but it's got kind of a cowboy edge to it. What's the history of the area?\n\nKris Hampton (02:20): Well, I mean, people have been climbing here for a long time. It really gained its popularity as a climbing town through Todd Skinner, who was one of the most famous climbers in the world in the 1990s. And his sister was a prospector or was living as a prospector here for a time while writing a book and saw these cliffs and called Todd, who was living in a teepee and over in South Dakota, and he came over to take a look at the cliffs and called back to South Dakota and said, pack all the stuff, bring it over here. And ironically, Todd is from Pinedale, Wyoming, just across the wind rivers from Lander, and he started developing and talking about the climbing here and Todd and Paul Piana and Amy Skinner and some of that crew used all these cowboy terms to name the roots and these western themed crags. And I just used the names that they had written, that they had named things to write this poem as something to give to the community after the first few times I came here.\n\nCole Heilborn (03:34): Did you settle in Lander because of the climbing opportunity?\n\nKris Hampton (03:39): No, not exactly. I met a woman here on my second trip now my wife and she grew up here, so eventually we found our way back here.\n\nCole Heilborn (03:50): Gotcha. Awesome. Well, Chris, I'd love if you could give us a quick introduction, a little bit of your background. You host a bunch of different podcasts, you're also a climbing coach and you've found a world where you can bring those two together. Could you give us a little background on what you do?", "token_estimate": 488, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "01:53", "end_timestamp": "03:50", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "3e5d3e01-3c88-4f0e-9288-e148d498e59b", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 2, "content": "Kris Hampton (04:08): Yeah, so actually it's interesting you just mentioned a way to bring those two worlds together. I sort of feel like that's been a lot of my life. I was a rapper, started rapping in the 1990s, early nineties, and eventually wrapped about rock climbing after I'd found climbing just sort of as a joke. But that led me to traveling and performing at all these festivals, and that's how I ended up here in Lander, Wyoming. And I eventually started a climbing coaching business. I've been doing that for a little over 10 years now, I think, and that I had all this audio background from rapping and I thought, well, gosh, I should just record all these conversations that I'm having. I've got all the equipment, I've got the know-how, let's make a podcast. And so I did. And that's the Power Company podcast, and I think we're about 270 episodes deep on that podcast. (05:09): And that sort of just became an obsession. And now I host the Power Company podcast, the Breaking Beta podcast, which is about the science of climbing. Hip hop taught me everything with my friend Devin Dabney, which is a storytelling podcast rooted in hip hop, and now I'm working on Built Outdoors for the Plug Tone Audio Network, which is a network I co-founded with my friends Devin Dabney and Emily Holland and Built Outdoors tells the story of outdoor entrepreneurs and is just a way to celebrate the small business owners in the outdoors while also telling great stories.\n\nCole Heilborn (05:55): On any given week, how many episodes are you typically recording? Amongst all of 'em?\n\nKris Hampton (06:01): I haven't the slightest idea. There are weeks where I put out four or five episodes across the different podcasts. There are weeks where I might record 10 episodes. That's probably the max. Like I said, it's an addiction and some weeks I just don't do it at all because I need the mental break.\n\nCole Heilborn (06:22): That's ridiculous. 10 episodes in a week, I feel like\n\nKris Hampton (06:27): It's an addiction.\n\nCole Heilborn (06:29): Are you the type of person who leaves a podcast interview feeling recharged and stoked for the next one, or do you need a day in between to kind of recharge?", "token_estimate": 551, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "04:08", "end_timestamp": "06:29", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "19785aa0-5371-47be-91fd-d7f75b1566bf", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 3, "content": "Kris Hampton (06:39): That's a great question. It depends on the Power Company podcast in particular. I mix it up between talking, training and really digging into some of the social issues and cultural issues within climbing. So while they do recharge some of my buckets, a lot of times they'll leave me emotionally drained, mentally drained, so I can't do a bunch of those type of episodes. But if I am splitting it up between let's talk the details of training or the science of training, let's have a conversation about deeper social issues, those things sort of come out of different buckets for me so I can fit a lot of those things into any given day.\n\nCole Heilborn (07:34): What's your background with climbing? How did you fall into that?\n\nKris Hampton (07:38): Well, actually I was a troublemaker when I was a kid, and I discovered around 16 or so that I was really good at stealing cars and stealing car stereos, but I was not very good at not getting caught. So I ended up going to jail when I was 18. And while locked up, I realized I needed a whole new set of friends, a whole new environment. I needed to just start over somewhere new. And I had gone to a climbing gym one time and having a background as a gymnast and as a skateboarder, I just sort of took to climbing and I really enjoyed that one time. So when I got out, I went straight to the climbing gym and I bought a month membership and I was in there every day for that month, and the manager was like, why don't you just vacuum the floors or something and then you don't have to buy another membership, you're here every day. Anyway, as soon as I get here, that was the last gym membership I ever bought and I've been climbing ever since.\n\nCole Heilborn (08:46): Wow. And the coaching business, how did that get started? When did you realize that you wanted to be able to share that experience with others?", "token_estimate": 471, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "06:39", "end_timestamp": "08:46", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "61edcdf1-62aa-428f-8fcf-859636a9ddaf", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 4, "content": "Kris Hampton (08:57): Well, I was training myself. I wanted to see how good I could become at climbing, and there wasn't a lot of information out there on how to improve at climbing, so it was a big experiment. And I started a blog called Power Company Climbing back in the days when blogs were cool, and I trained a few friends and I mentioned on the blog once that I had trained a few friends and then I got inundated with requests, so I wrote a bunch of training programs That Winter realized the way I was doing it was unsustainable. And shortly after, tried to find a way, worked on an app that we now use to train people through and just figured out a better way to communicate and a way to sort of take climbing training to a bigger platform. And as soon as I released that to the public and opened myself up for business pretty immediately, I knew I had to quit my full-time job as a mural painter. So I gave them my two weeks almost immediately, and now that's my full-time job and I have a bunch of coaches that work with me and my office manager, and it's just, for me, it's a great way to reach the community and help people become not just better at climbing, but become better climbers, better humans, and be more resilient throughout their real lives.\n\nCole Heilborn (10:36): So I've always been curious, you think about the trajectory of becoming good at anything, and if 10 is perfect and zero is a beginner, when you're working with folks and maybe you aren't working with folks who are brand new, but from that zero to one or zero to two spot in learning a new skill, what is something that new climbers always struggle with that they probably don't anticipate being the thing being the crux that they're dealing with currently?", "token_estimate": 437, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "08:57", "end_timestamp": "10:36", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "68b258a5-2089-4696-b8bd-964f5060ba9c", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 5, "content": "Kris Hampton (11:07): I do work with new climbers and expert level climbers, and I think climbing is such an interesting sport that sort of scales itself. The experts are dealing with the same sort of struggle that the relatively new climbers are just at a different difficulty level. So I think really the thing that sort of permeates the entire sport from beginner all the way to the top levels are just doubts and doubts about exploration. We sort of come in with expectations of how something is supposed to feel when it doesn't feel that way. We end up with all these doubts and we're not willing to explore anymore, and we just get on ourselves. So encouraging both beginners and experts to continue exploring, I think is exploring their movement and their own confidence levels I think is really the biggest thing all the way across the board.\n\nCole Heilborn (12:12): Interesting. So that confidence component to never stop exploring, never stop discovering a new route or new holds\n\nKris Hampton (12:19): Or new ways to move, new ways to fit yourself between holds. Creativity is such a big part of just about any eSport climbing in particular, I think for me feels very creative and I try to encourage people not to lose that.\n\nCole Heilborn (12:41): So you're 230 some episodes deep in your podcast. You started in, did you say 2016?\n\nKris Hampton (12:48): Gosh, I honestly don't know. Dates are probably my weakest area of anything. I'm terrible at dates. If I can't connect it to a big momentous event in my life, like graduating from high school or having my first daughter, then I can't tell you the date.\n\nCole Heilborn (13:09): Fair enough. Was this before or after having your daughter? Did you start your podcast\n\nKris Hampton (13:13): After?\n\nCole Heilborn (13:14): Okay,\n\nKris Hampton (13:15): After my first daughter who's now 25, she'll be 25 in three days.", "token_estimate": 470, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "11:07", "end_timestamp": "13:15", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "33baa811-b68b-4eb5-95ea-bce5507ce300", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 6, "content": "Cole Heilborn (13:21): Okay. Well, congrat, happy birthday, happy early birthday. So 2016, I think I read that somewhere. That's a considerable amount of time to be in the podcast world, especially as podcasting in the last two years or three years has really become popular and mainstream. I feel like you've been doing this well Beyond me, well beyond many people. What have you noticed? What differences do you notice about the podcast landscape from then to now?\n\nKris Hampton (13:52): Well, it's definitely gotten more crowded, and I don't say that as a bad thing. I think as it's grown, just like anything else, I saw this with hip hop when I was really into hip hop. I saw it become easier for people to make things, and that's certainly happened in the podcast world. It's much easier now to make a podcast, put a podcast out there, and I think that's led to it's splitting off into there are some really, really bad podcasts because anybody can make one and the price of entry is pretty low. But then there are also some really creative, really great podcasts out there, and it's really hard for me to keep up. I want to really badly. I want to listen to everything good that's out there, but it's so hard to keep up. What I do find, however, inspires me to keep growing, to keep improving at podcasting and to keep being able to tell better stories.\n\nCole Heilborn (14:57): Interesting. You bring that up because that's kind of at the heart of where I'm hoping we can take this conversation. And I was trying to think about, so we had a conversation before this about you and your business and everything that you do, and the thing that I took away from our conversation was this idea of focus and there's so much that you can be doing as a podcaster and there's only so much time, you only have so much bandwidth. And so it sounds like what you're saying is that finding that focus has been really important. And I'm curious how focus has changed the idea of focus has maybe changed over time as you've been podcasting?", "token_estimate": 508, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "13:21", "end_timestamp": "14:57", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "fbcf43a3-b65a-47e0-97ab-b8803121c72b", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 7, "content": "Kris Hampton (15:36): Yeah, I think for me specifically, initially podcasting was all about getting training information out there, and then once I realized I had people's ear and that I could tell them more important things than just how to make your fingers stronger, then I leaned a little more toward the idea of telling the stories that aren't necessarily being told in climbing and hearing from the voices that we aren't hearing from. So that's been a big part of this for me. And now I'm just leaning more toward how can I tell stories in a bigger, more memorable way. So for me, that's how it's changed and how I've changed my focus. But this is my main marketing tool. The Power Company podcast is my main marketing tool for sure. So I also have to make sure that I'm marketing my business in the process. So there's definitely a balance there between telling other people's stories and also telling our own story.\n\nCole Heilborn (17:02): Yeah. How much of your time is spent actually podcasting versus being a coach?\n\nKris Hampton (17:12): That shifted quite a bit over the years. It started out I was doing one episode a month or something, so very small percentage of my time was spent podcasting. Now because podcasting is what I'm really excited about and learning to tell better stories is what I'm excited about. I would say I spend probably 70 to 75% of my time working on podcasts and podcast ideas.\n\nCole Heilborn (17:42): Interesting. And the marketing side of it all, how much does the podcast play the marketing of your coaching business?", "token_estimate": 390, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "15:36", "end_timestamp": "17:42", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "59746c2b-b812-44f1-ae6a-70fa40b2d075", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 8, "content": "Kris Hampton (17:52): It's huge. I don't spend a lot of time directly pointing people towards the products that we make, and we have a lot, the reason I can spend 70 to 75% of my time making podcasts because we have a lot of passive offerings for climbers, eBooks, and training plans through our apps and things like that and products that we sell. And I don't spend a lot of time pushing people in that direction. But what I do through the podcast is put my expertise out there as a climber, as a climbing coach, as someone who's spent a lot of time reading books, listening to other podcasts, talking with coaches across a variety of different sports, reading research into training across a bunch of different sports and trying to synthesize all that into how can we be better climbers. So for me, putting my expertise out there front and center brings people into this company and by taking stands on the podcast on things that I believe in and trying to tell stories that I believe in, I know that I'm getting a certain type of customer who isn't going to be something dramatically different from the type of person that we want to work with.\n\nCole Heilborn (19:21): Yeah, interesting. So I feel like if I go onto LinkedIn at any point during the week, I will see a post somewhere about how there's some clickbaity title that says you need to create a podcast because it will become your number one marketing tool, which I don't necessarily disagree with. However, I'm curious if you've been doing it for this long, when did you realize that the podcast was giving you more value than you were putting into it? When did you start making a profit essentially off of your podcast and the time and the energy invested?", "token_estimate": 430, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "17:52", "end_timestamp": "19:21", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "92acf2cb-f962-447d-8aee-503b28dbef4e", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 9, "content": "Kris Hampton (19:59): It actually happened pretty quickly for me, but I think that's largely because of the timing of getting into it early before there were many climbing podcasts and then putting out a consistent product for over several years. So I earned the trust of the climbing community through this podcast. I think that you're totally right with these Click Beatty titles, and it sort of felt like at the time if you build it, they will come scenario like, oh, I just made a podcast and people bought in and now they're coming to my website. But as the podcast landscape gets more and more crowded and there are more and more podcasts out there that put out three or four episodes and then never show up again, it's getting harder and harder to earn people's trust. So I don't think it's the case that you can just build it and they will come. I think you really have to put the work in, be consistent care about the product that you are putting out there into the airwaves, and then maybe you can earn the trust of people.\n\nCole Heilborn (21:19): Yeah. Yeah. It's that trust that's the variable in all of it. How do you build that? How do you foster it, and how long do you have to keep plugging away at it before you slowly start to build that bridge?\n\nKris Hampton (21:37): Yeah, I wish I knew the answers to any of those questions. For me, it's just keep doing it. I don't do anything that I don't want to do. I'm not going to make a podcast just as a marketing tool if I don't want to have these conversations. It's going to show in the conversation that I don't want to be there. So for me, if I'm going to do something, it's something I'm going to be excited about that I can keep doing. And I think that's how you build the trust. You are excited about it, you continue doing it even when there are five listeners and you just steadily build that.\n\nCole Heilborn (22:21): How do you think about the marketing of your podcast and the marketing of your business?", "token_estimate": 495, "speakers": ["Kris Hampton", "Cole Heilborn"], "start_timestamp": "19:59", "end_timestamp": "22:21", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "fd746c96-410e-4ce9-aeec-7349011589a7", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 10, "content": "Kris Hampton (22:28): That's definitely changed too. Initially, I didn't have to worry about it. I was one of the few blogs talking about training for climbing. I was one of the few podcasts out there talking about climbing, and I think I had a better audio product than several of the other podcasts because I was doing all of my interviews in person and I had a background with audio, so I understood it a little. And now as it gets more and more crowded as it's harder and harder to reach people in a landscape where they have literally hundreds and hundreds of options to choose from, I have to be a little more thoughtful. And I've sort of narrowed it down to three principles that I try to always follow. And number one is be authentic. And that just means, like I just said, if I'm not excited about it, don't do it. I have to think it's cool. I have to think it's exciting, I have to feel good about it, I have to believe in it. And then number two is keep trying new things, but do it with healthy skepticism. (23:43): When new things come out, I'm old and crusty and I'm like, I'm not doing that. That's ridiculous. But I'm willing to try and see how it feels to me, see how it works. And I go in with a lot of skepticism. I don't just buy in immediately because it's the thing everyone's talking about. And last is a quote that I take from a strength coach named Dan John, and we use this quote in my training business often, and that's the goal, is to keep the goal the goal. And that simply means whatever my original goal is when I set out to make the thing to market the thing, I make sure that remains the goal. If my goal, let's say in climbing, the goal is to climb better, but very often people get sidetracked and in their training, they want to make their fingers stronger, and all of a sudden their whole goal is, I want to make my fingers stronger. And they forget that the goal initially was to become a better climber. And I think with making things like making a podcast, my goal is to tell good stories and get voices out there that aren't being heard. But if I'm worried about how my reels translate on Instagram, I start paying more attention to the likes I'm getting or how many views my reel gets, and now all of a sudden I'm putting all my energy toward how do I get more views on this reel? And I've lost what the actual goal is.", "token_estimate": 591, "speakers": ["Kris Hampton"], "start_timestamp": "22:28", "end_timestamp": "22:28", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "9838da18-296b-4bca-987e-c65081bed7c5", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 11, "content": "Cole Heilborn (25:18): Interesting. Dan John, is that the individual who came up with that idea?\n\nKris Hampton (25:24): Yeah, he's this common sense, no bullshit strength coach, world famous strength coach who he's just brilliant. He can really pare things down into their essence and just give you a sentence that smacks you in the face.\n\nCole Heilborn (25:47): That's such a simple idea. But I'm even thinking about myself and goals that I have or goals that I set years ago. And I'm now wondering, huh, maybe have I lost track of that original goal? Have I replaced it with something else? And I got to imagine in today's world, it's even that much easier to do where there's always a new tool, there's always a new bandwagon to jump on, or there's TikTok blows up, and now we're all supposed to be using that.\n\nKris Hampton (26:18): It's so hard to not get distracted from what your original goal is. It's a thing I have to constantly ask myself. I have to remind myself every single day, this is why I'm doing this. This is the goal of this thing. Don't get distracted down these rabbit holes because I love rabbit holes, Cole, I love going down rabbit holes and learning new things, but I've only got so much room and so much growth potential. I have to focus on the things that are my actual goals.\n\nCole Heilborn (26:55): Do you have a story? Do you have an example of where you've distracted yourself and you've had to course correct?\n\nKris Hampton (27:01): Yeah. I mean, certainly with climbing it happens very easily because I love training. I love the minutia of getting stronger, of improving at something. And if left to my own devices, I could very easily just disappear into the gym and never come back out. So for myself, if I don't remind myself I need to go out and actually climb things and try the thing that started this whole process, if I don't do that, I'll stay in the gym and just keep trying to get stronger fingers. I think that's super common. And for me, that's definitely the case. I love going into the gym. I would choose to go into the gym over climbing outside a lot of days if I didn't remind myself to go out there.", "token_estimate": 539, "speakers": ["Cole Heilborn", "Kris Hampton"], "start_timestamp": "25:18", "end_timestamp": "27:01", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}, {"id": "f86a4ef3-33f5-4bb6-a4f9-5fe263f9a2fa", "episode_id": "0e275986-db48-4416-950f-29cdb01f433d", "cms_item_id": "68225dfc7bb476527f8c489a", "chunk_index": 12, "content": "Cole Heilborn (28:00): And I can see that being translated into a professional sense or a career sense quite easily. I'm thinking about us personally with this podcast, I guess similar to you. So for this podcast, for us, it's a lot of things. It's a way for us to continue to learn. It's a way to educate ourselves. It's also a way it has become a marketing and a sales tool for our production company. And my real job is producing commercials and films, and this podcast is just kind of the cherry on top where I get to have fun conversations with folks, but I will frequently wake up and think I'll spend most of my time thinking about the podcast, and I spend hardly any time actually thinking about the thing that pays my bills and helps pay our team's bills. And I don't think that that's necessarily wrong, but this idea of the goal is to keep the goal of the goal has got me thinking about all the places where I find myself getting distracted. And yeah, I don't know. I don't have a thought other than that's just where my mind's at right now.", "token_estimate": 263, "speakers": ["Cole Heilborn"], "start_timestamp": "28:00", "end_timestamp": "28:00", "podcast_index": 120, "episode_name": "EP 120: Break All The Rules | Kris Hampton | Power Company Climbing", "slug": "ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-120-break-all-the-rules-kris-hampton-power-company-climbing", "guest_name": "Kris Hampton", "guest_title": "Podcaster", "categories": [], "short_description": "Kris Hampton (he/him) is a former mural painter and rapper, currently a climbing coach and outdoor industry podcaster who has modeled his business after what he understood - independent hip-hop labels.", "podcast_length": "58:55"}]
